           prbs_vld,
           prbs_out,

           pcs_prbs_ber_cnt,
           pcs_prbs_ber_cnt_overflow,
           pcs_prbs_ber_soft_reset,

           scan_mode,
           icg_mode,
           mbist_mode
   );

input                                   clk;
input                                   rst_n;

input                                   prbs_en;
input   [3:0]                           prbs_mode;
// input                                   prbs_loop;

input   [19:0]                          prbs_in;
output                                  prbs_vld;
output  [19:0]                          prbs_out;

output [15:0]                           pcs_prbs_ber_cnt;
output                                  pcs_prbs_ber_cnt_overflow;
input                                   pcs_prbs_ber_soft_reset;

input                                   scan_mode;
input                                   icg_mode;
input                                   mbist_mode;


