module M2_clci_rx_lane_sync #(
parameter DATA_CH_NUM = 16
)
(
    input                       clk,
    input                       rstn,
    input [1:0]                 l16_l8_l4_mode,
    input [15:0]                pcs_fh_loop_num,
    
    input                       rx_lock_all,
    input [DATA_CH_NUM-1:0]     rx_flag,
    input [DATA_CH_NUM*20-1:0]  rx_data,
    output [1:0]                rx_lane_mux_cnt,
    output[DATA_CH_NUM*20-1:0]  rx_data_out,
    output reg                  rx_data_fh,
    output reg                  rx_lane_sync,
    output                      rx_sample_en,

    output reg  [DATA_CH_NUM*3-1:0]    sync_sel
);


