// Last Modified    : 
// Description      : replace cl2103 crc polynomial 0x8005 to 0xA2EB
//                    both 0x8005 and 0xA2EB support HD4, but for HD5,
//                    0xA2EB error miss detect ratio is half to 0x8005.
//                    
//=======================================================================
`timescale 1ns/1ps    
//-----------------------------------------------------------------------------
// CRC module for data[299:0] ,   crc[15:0]=1+x^1+x^3+x^5+x^6+x^7+x^9+x^13+x^15+x^16;
//-----------------------------------------------------------------------------
module M2_clci_ce_encode (
  input [301:0] data_in,
  input         crc_ecc_sel, // 0 - crc, 1 - ecc
  input         f_flag,
  output reg    f_flag_o,
  input         sample_en,
  output reg    sample_en_o,
  output [315:0] data_out_ce,
  input         rstn,
  input         clk

);

  //reg [15:0] lfsr_q,lfsr_c;
  
