module M2_clci_tx_ctrl(
    input                        clk                                            ,
    input                        rstn                                           ,
    
    input                       pcs_mac_tx_ready_enable,
    input [317:0]        mac_tx_in                              ,
    input                            mac_tx_vld                             ,
    output reg           clci_mac_valid                     ,
    output               mac_tx_trdy                        ,
    
    input   [7:0]                        otherside_ok_id                    ,
    input                            otherside_ok_id_vld            ,

    output reg [317:0] mac_tx_prescramble             , //no crc ,no scramble
    output reg         mac_tx_h_flag                        ,
    output reg         mac_tx_h_sample_en,
                              
    input                            clci_tx_en                             ,   
    input       [1:0]            rx_lock    ,
    output                  pcs_retry_timeout,
    input       [7:0]       pcs_retry_cnt,
    input                   pcs_retry_cnt_ctrl,
    input                   pcs_retry_cnt_clear,
    output      [15:0]      pcs_max_retry_cnt,
    input       [6:0]       retry_buf_depth_true,
    input       [1:0]       l16_l8_l4_mode,
    input       [15:0]      pcs_fh_loop_num,
    output                  rx_lock1_fh_cnt_equal2

    
);

