module M2_clci_tx_lane_demux
    #(
    parameter   LANEWIDTH = 20
    )
    (
//---------------------- input --------------------------
    input       [1:0]               lane_mode,  // 0, 3:16 lane, 1:8 lane, 2:4 lane
    input       [1:0]               dat_cnt,
    input       [LANEWIDTH*16-1:0]  data_in,
//---------------------- output -------------------------
    output  reg [LANEWIDTH*16-1:0] data_out
    );


