module M2_clci_adapter_tx_cmdback(
    input               clk,
    input               rstn,
    
    input   [7:0]       rx_ptr,//
    input   [7:0]       rx_ptr2,//
    input   [7:0]       rx_ptr3,
    input   [7:0]       rx_ok_id,
    
    input               tx_flag,
    input               sample_en,
    input               tx_en,
    input   [1:0]       l16_l8_l4_mode,
    
    output  [3:0]       tx_cmdback_data,
    output  reg         tx_cmd_16t_trig
);
