module M2_clci_adapter_tx_ctrl
    #(
    parameter  PARITY_MODE_SEL = 0
    )
    (
    input               clk,
    input               rstn,
    
    input [1239:0]      mac_tx_in,
    input               mac_tx_vld,
    output reg          clci_mac_valid,
    
    input   [7:0]       otherside_ok_id,
    input               otherside_ok_id_vld,

    output reg [1249:0] mac_tx_prescramble, //no crc ,no scramble
    output reg          mac_tx_h_flag,
    output reg          mac_tx_h_sample_en,
    output reg          mac_tx_h_cmd_sample_en,
                              
    input               clci_tx_en,   
    input       [1:0]   rx_lock,
    output              pcs_retry_timeout,
    input       [7:0]   pcs_retry_cnt,
    input               pcs_retry_cnt_ctrl,
    input               pcs_retry_cnt_clear,
    output reg  [15:0]  pcs_max_retry_cnt,
    input       [6:0]   retry_buf_depth_true,
    input       [1:0]   l16_l8_l4_mode,
    input       [15:0]  pcs_fh_loop_num,
    output              rx_lock1_fh_cnt_equal2,
    input               retry_pause,
//-----------------------------------------------------------
    input               rdi_pl_tx_fh,
    output  reg         rdi_pl_tx_valid,
//-----------------------------------------

    output              buf_adapter_tx_ctrl_retry_empty , 
    input               scan_mode
);

