`define __M2_CLCI_ADAPTER_TX_GEARBOX_1TO4__

`resetall
`timescale 1ns/1ps

module M2_clci_adapter_tx_gearbox_1to4
        (
//------------------ general ----------------
        input                   clk,
        input                   rst_n,

//-------------------------------------------
        input       [1:0]       l16_l8_l4_mode,
        input       [1:0]       rx_link_status,
        input                   tx_in_true_vld,
        input                   tx_h_flag,
        output                  tx_in_1to4_rdy,
        input                   tx_in_1to4_vld,
        input       [1271:0]    tx_in_1to4_dat,

        input                   tx_out_1to4_rdy,
        output                  tx_out_1to4_vld,
        output reg  [317:0]     tx_out_1to4_dat
        );



