// Author        : liang.zeng
// Created On    : 2024-05-13 15:01
// Last Modified : 
// -----------------------------------------------------------------
// Description:

//16lane + 2lane * 20bit
//16 txclk. 16 rxclk. 1 aclk. aclk >= txclk
//256 AXI4 interface

`ifndef __M2_CLCI_UCIE_ADAPTER__
`define __M2_CLCI_UCIE_ADAPTER__

`resetall
`timescale 1ns/1ps

module M2_clci_ucie_adapter #(
parameter AXI_ADDR_WIDTH = 5,
parameter DATA_CH_NUM = 16,
parameter SYNC_LEVEL = 2,
parameter PARITY_MODE_SEL = 0
)
(
//--------------------------------------------- UCIE signals ---------------------------------------------
//------------------------------ general -------------------------------
    input                                                       fdi_lclk_tx,
    input                                                       fdi_lclk_rx,

//---------------------- Protocol to the Adapter -----------------------
//--------------------------------- TX ---------------------------------
    input                                                       fdi_lp_irdy,
    input                                                       fdi_lp_valid,
    input           [309:0]                                     fdi_lp_data, //actually should be [NBYTES-1:0][7:0], this data width only for clci ucie
    input                                                       fdi_lp_retimer_crd,
    input                                                       fdi_lp_corrupt_crc,
    input           [7:0]                                       fdi_lp_dllp,
    input                                                       fdi_lp_dllp_valid,
    input                                                       fdi_lp_dllp_ofc,
    input           [7:0]                                       fdi_lp_stream,
    output                                                      fdi_pl_trdy,

//--------------------------------- RX ---------------------------------
    output                                                      fdi_pl_valid,
    output          [309:0]                                     fdi_pl_data, //actually should be [NBYTES-1:0][7:0], this data width only for clci ucie
    output                                                      fdi_pl_retimer_crd,
    output          [7:0]                                       fdi_pl_dllp,
    output                                                      fdi_pl_dllp_valid,
    output                                                      fdi_pl_dllp_ofc,
    output          [7:0]                                       fdi_pl_stream,

    output                                                      fdi_pl_flit_cancel,
    input           [3:0]                                       fdi_lp_state_req,
    input                                                       fdi_lp_linkerror,
    output          [3:0]                                       fdi_pl_state_sts,
    output                                                      fdi_pl_inband_pres,

    output                                                      fdi_pl_error,
    output                                                      fdi_pl_cerror,
    output                                                      fdi_pl_nferror,
    output                                                      fdi_pl_trainerror,

    output                                                      fdi_pl_rx_active_req,
    input                                                       fdi_lp_rx_active_sts,   //------- connect to *ready signal?

    output          [2:0]                                       fdi_pl_protocol,
    output          [3:0]                                       fdi_pl_protocol_flitfmt,
    output                                                      fdi_pl_protocol_vld,

    output                                                      fdi_pl_stallreq,
    input                                                       fdi_lp_stallack,

    output                                                      fdi_pl_phyinrecenter,
    output                                                      fdi_pl_phyinl1,
    output                                                      fdi_pl_phyinl2,
    output          [2:0]                                       fdi_pl_speedmode,

    output          [2:0]                                       fdi_pl_lnk_cfg,
    output                                                      fdi_pl_clk_req,
    input                                                       fdi_lp_clk_ack,
    input                                                       fdi_lp_wake_req,
    output                                                      fdi_pl_wake_ack,

//------------------------ Adapter to the LPHY -------------------------
//--------------------------------- TX ---------------------------------
    output                                                      rdi_lp_irdy,
    output                                                      rdi_lp_valid,
    output          [319:0]                                     rdi_lp_data,
    output                                                      rdi_lp_retimer_crd,
    input                                                       rdi_pl_trdy,
    input                                                       rdi_pl_tx_fh_flag,

//--------------------------------- RX ---------------------------------
    input                                                       rdi_pl_valid,
    input           [319:0]                                     rdi_pl_data,
    input                                                       rdi_pl_retimer_crd,
    input                                                       rdi_pl_rx_fh_flag,

    output          [3:0]                                       rdi_lp_state_req,
    output                                                      rdi_lp_linkerror,
    input           [3:0]                                       rdi_pl_state_sts,
    input                                                       rdi_pl_inband_pres,
    input                                                       rdi_pl_error,
    input                                                       rdi_pl_cerror,
    input                                                       rdi_pl_nferror,
    input                                                       rdi_pl_trainerror,
    input                                                       rdi_pl_phyinrecenter,
    input                                                       rdi_pl_stallreq,
    output                                                      rdi_lp_stallack,
    input           [2:0]                                       rdi_pl_speedmode,
    input           [2:0]                                       rdi_pl_lnk_cfg,
    input                                                       rdi_pl_clk_req,
    output                                                      rdi_lp_clk_ack,
    output                                                      rdi_lp_wake_req,
    input                                                       rdi_pl_wake_ack,

//clk rstn
    input                                                       clk,
//  input                                                       rstn,
    input                                                       tx_clk_rstn,
    input                                                       rx_clk_rstn,
    //input                                                       pclk,
    //input                                                       presetn,

    input                                                       scan_mode,
    input                                                       icg_mode,
    input                                                       mbist_mode,
    input                                                       async_mode,
    input                                                       pcs_mac_tx_ready_enable,
    // input                                                       pcs_error_inject,
    // input                                                       pcs_error_inject_mode,
    input       [15:0]                                          pcs_fh_loop_num,
    input                                                       scramble_mode,
    input       [1:0]                                           l16_l8_l4_mode,
    input                                                       diff_mode,  // 1: differencial mode, 0: single mode
    input       [7:0]                                           lane_pn_sel, //1:from P port, 0:from N port
    input       [1:0]                                           tx_sfifo_afull_thsh_ctrl,
    
    input       [DATA_CH_NUM-1:0]                               tx_rstn,  //rdy

    input       [DATA_CH_NUM-1:0]                               rx_rstn,  //rdy
                                                                            
                                                            
//slip                                                      
    output      [DATA_CH_NUM-1:0]                               rx_slip,
    input       [DATA_CH_NUM-1:0]                               rx_phase,

//flag
//    input      [7:0]                                            rx_ok_id,


//pma tx phase loopback.                                
    // input                                                       tx_phase_en,
    input                                                       pcs_prbs_en_all_lane_tx,
    input                                                       pcs_prbs_en_all_lane_rx,
    input       [DATA_CH_NUM-1:0]                               pcs_prbs_en_rx,
    input       [DATA_CH_NUM-1:0]                               pcs_prbs_ber_soft_reset_rx,

    input       [20*DATA_CH_NUM-1:0]                            tx_phase_data,
    output      [DATA_CH_NUM*4-1:0]                             tx_phase_sel,
    output      [DATA_CH_NUM-1:0]                               tx_phase_check_ok,
    output  reg                                                 tx_phase_check_done,
    input       [DATA_CH_NUM-1:0]                               pcs_prbs_en_tx,
    output      [DATA_CH_NUM*16-1:0]                            pcs_prbs_ber_cnt_rx,
    output      [DATA_CH_NUM-1:0]                               pcs_prbs_ber_cnt_overflow_rx,
    
    input       [23:0]                                          rx_buf_status,    // new added, used for flow ctrl

    output                                                      otherside_rx_buf_vld,   // new added, used for flow ctrl
    output  reg [23:0]                                          otherside_rx_buf_status,   // new added, used for flow ctrl

//cfg status.no bus.reg in 
    input                                                       pcs_err_test_en,
    output      [16*DATA_CH_NUM-1:0]                            lanex_err_num,
    input                                                       scramble_bypass,
    input                                                       crc_ecc_sel,
    input                                                       clci_tx_en,
    input                                                       rx_lane_rev,
    input       [6:0]                                           pcs_retry_buf_depth,
    output      [DATA_CH_NUM-1:0]                               rx_fh_lock, 
    output                                                      rx_lane_sync,
//    output      [1:0]                                           rx_link_status,
    output      [1:0]                                           rx_link_status_tx_domain,
    input       [1:0]                                           rx_link_status_lphy,
    output                                                      rx_lock1_fh_cnt_equal2,
    output reg  [31:0]                                          ecc_correct_cnt,
    output reg  [31:0]                                          ecc_crc_dec_ok_cnt,
    input                                                       pcs_retry_cnt_ctrl,
    input                                                       pcs_retry_cnt_clear,
    input                                                       ecc_cnt_clear,
    input       [7:0]                                           lock_value_reg,
    input       [7:0]                                           pcs_retry_cnt,
    output      [15:0]                                          pcs_max_retry_cnt,
    input       [31:0]                                          pcs_scrmb_seed,
    input                                                       adapter_tx2rx_loop,
    
    output      [103:0]                                          debug_signal,
//-----------------------------------------

//----------------------------------------- irq -----------------------------------------
    output                                                      pcs_rx_link_done0,
    output                                                      pcs_rx_link_done1,
    output                                                      pcs_crc_error,
    output                                                      pcs_cmd_crc_error,
    output                                                      pcs_retry_timeout,
    output                                                      pcs_retry_id_timeout,

    input                                                       retry_pause,

// --------------------------------parity check---------------------------------------
    output                                                      buf_adapter_tx_ctrl_retry_empty ,  // tx_gated_clk 
    output                                                      buf_adapter_tx_first_empty      ,  // tx_gated_clk
//---------------------------------- sideband edge trig ----------------------------------
    output                                                      tx_cmd_16t_trig 
);

//----------------------------------------------------------------

`protected128
