//////////////////////////////////////////////////////////////////////////////////////
// RDI interface : begin
//////////////////////////////////////////////////////////////////////////////////////
output                                 rdi_lclk_tx;
output                                 rdi_lclk_rx;

// TX interface
input                                  rdi_lp_irdy;
input                                  rdi_lp_valid;
input       [319:0]                    rdi_lp_data;
output                                 rdi_pl_trdy;
output                                 rdi_pl_tx_fh_flag;

input                                  rdi_lp_retimer_crd; // retimer only, not used

// RX interface
output                                 rdi_pl_valid;
output      [319:0]                    rdi_pl_data;
output                                 rdi_pl_rx_fh_flag;

output                                 rdi_pl_retimer_crd; // retimer only, not used

// RDI status exchange.
input       [3:0]                      rdi_lp_state_req;
input                                  rdi_lp_linkerror;

output      [3:0]                      rdi_pl_state_sts;
output                                 rdi_pl_inband_pres;
output                                 rdi_pl_error;
output                                 rdi_pl_cerror;
output                                 rdi_pl_nferror;
output                                 rdi_pl_trainerror;
output                                 rdi_pl_phyinrecenter;

// clock_gating handshake 
output                                 rdi_pl_stallreq;
input                                  rdi_lp_stallack;

output      [2:0]                      rdi_pl_speedmode;
output      [2:0]                      rdi_pl_lnk_cfg;

// clock gating enalbe handshake.
output                                 rdi_pl_clk_req;
input                                  rdi_lp_clk_ack;

// wake up handshake
input                                  rdi_lp_wake_req;
output                                 rdi_pl_wake_ack;

// sideband interface from phy interface to adapter
//output  [31:0]                         rdi_pl_cfg;
//output                                 rdi_pl_cfg_vld;
//input                                  rdi_pl_cfg_crd;

// sideband interface from adapter to phy interface 
//input  [31:0]                          rdi_lp_cfg;
//input                                  rdi_lp_cfg_vld;
//output                                 rdi_lp_cfg_crd;

//////////////////////////////////////////////////////////////////////////////////////
// RDI interface : end
//////////////////////////////////////////////////////////////////////////////////////

// From/To register
input  [19:0]                          lphy_rdi_req_exchange;
output [8:0]                           lphy_rdi_status_exchange;

//////////////////////////////////////////////////////////////////////////////////////
// legacy SPHY interface : begin
//////////////////////////////////////////////////////////////////////////////////////
input                           reset_n;
input [CH_NUM-1:0]              channel_reset;
input [CH_NUM-1:0]              prbs_en_ch;

input                           pclk;
input                           presetn;

// input                           aclk;
input                           aresetn;

// scan_mode
// input                           scan_mode;
input                           test_mode;
input                           scan_en;
// input                           pll_bypass;
// input                           icg_mode;
// input                           mbist_mode;
// input                           scan_clk_aclk;
input                           scan_clk_pclk;
input                           scan_clk_20;
input                           scan_clk_20_tx;
input                           scan_clk_20_rx;
input                           scan_clk_80;
// input                           scan_clk_66;

// output [CH_NUM-1:0]             irq_n;
output [CH_NUM-1:0]             clci_st_s_bist_correct_clk;



