`timescale 10 ps/1 ps

module M2_post_mac2201_top
#(
    parameter SYNC_LEVEL = 2,
    parameter  PARITY_MODE_SEL = 0
) (
//------------------------------ config -------------------------------
        input                   legacy_mode,
        input                   phy0_disable,
        input                   phy1_disable,
        input                   tx_afifo_bypass,
        input                   rx_afifo_bypass,
        input   [31:0]          port_num,
        input   [3:0]           pcs0_arbiter0_port0_wt,
        input   [3:0]           pcs0_arbiter0_port1_wt,
        input   [3:0]           pcs0_arbiter0_port2_wt,
        input   [3:0]           pcs0_arbiter0_port3_wt,
        input   [3:0]           pcs0_arbiter0_port4_wt,
        input   [3:0]           pcs0_arbiter0_port5_wt,
        input   [3:0]           pcs0_arbiter0_port6_wt,
        input   [3:0]           pcs0_arbiter0_port7_wt,
        input   [7:0]           pcs0_rx7_buf_thsh,
        input   [7:0]           pcs0_rx6_buf_thsh,
        input   [7:0]           pcs0_rx5_buf_thsh,
        input   [7:0]           pcs0_rx4_buf_thsh,
        input   [7:0]           pcs0_rx3_buf_thsh,
        input   [7:0]           pcs0_rx2_buf_thsh,
        input   [7:0]           pcs0_rx1_buf_thsh,
        input   [7:0]           pcs0_rx0_buf_thsh,
        input                   pcs0_port2_tx_pause,
        input                   pcs0_port4_tx_pause,
        input                   pcs0_port5_tx_pause,
        input                   pcs0_port7_tx_pause,
        input   [3:0]           pcs0_afifo_thsh,




        input                   stream_mode,
        input                   stream_rx_ff_bypass,

//------------------------------- port2 -------------------------------
        input                   port2_clk,
        input                   port2_rst_n,
//        output                  port2_fetch_num_err_intr,
        output                  port2_pcs0_rx_wr_full,
        input                   port2_pcs0_wr_full_otherside,
        output  reg             port2_pcs0_rx_afifo_overflow,
        output  reg             port2_pcs0_tx_afifo_overflow,
//---------------------------- TX ---------------------------------
        input                   port2_tx_dat_vld,
        output                  port2_tx_dat_ready,
        input   [291:0]         port2_tx_dat,
//---------------------------- RX ---------------------------------
        output                  port2_rx_dat_vld,
        input                   port2_rx_dat_ready,
        output  [291:0]         port2_rx_dat,




//-------------------------------- pcs interface ------------------------------
        input                   pcs0_tx_clk,
        input                   pcs0_tx_rst_n,
        input                   pcs0_rx_clk,
        input                   pcs0_rx_rst_n,

//-------------------------- to pcs0 ------------------------------
        output                  pcs0_tx_dat_vld,
        input                   pcs0_tx_dat_ready,
        output  [309:0]         pcs0_tx_dat,
//------------------------- from pcs0 -----------------------------
        input                   pcs0_rx_dat_vld,
        input   [309:0]         pcs0_rx_dat,


//----------------------------------------------------------------


        output                      buf_post_mac2201_port2_pcs_rx_empty     ,
        output                      buf_post_mac2201_port4_pcs_rx_empty     ,
        output                      buf_post_mac2201_port5_pcs_rx_empty     ,
        output                      buf_post_mac2201_port6_pcs_rx_empty     ,
        output                      buf_post_mac2201_port2_pcs_tx_empty     ,
        output                      buf_post_mac2201_port4_pcs_tx_empty     ,
        output                      buf_post_mac2201_port5_pcs_tx_empty     ,        
        output                      buf_post_mac2201_port6_pcs_tx_empty     ,     
        output                      buf_post_mac2201_port4_ctrl_rx_empty    ,
        input                   scan_mode
        );


