`ifndef M2_SWRR_ARBITER_SV_MODULE
`define M2_SWRR_ARBITER_SV_MODULE
//=======================================================================
// Copyright 2022@M2SEMI Technologies, Inc.
// Created by       : xcliu
// Filename         : swrr_arbiter.sv
// Created On       : 2022-08-02 10:07
// Last Modified    : 2022-09-23 10:39
// Description      : smooth weighted round-robin 
//
//                    1) support 8-channel input
//                    2) each channel support fixed priority or swrr
//  
// Revision         :
//      2022/12/17      change weight calculation method: config 0~15
//                      corresponding to add 1~16
//                    
//=======================================================================
`timescale 1ns/1ps  
                      
module  M2_swrr_arbiter #(
    parameter   DATA_W      = 320    ,
    parameter   OUTREG_EN   = 0         // 1, 0
) 
(
    input   logic                   pcs_rst_n       ,
    input   logic                   pcs_clk         ,
    input   logic                   legacy_mode     ,
    input   logic [5:0]             chs_arbiter_gap ,   // arbiter granularity
    input   logic [7:0]             chs_fixed_mode  ,   // fixed priority > swrr
    input   logic                   chs_ready       ,
    input   logic [7:0]             chs_vld         ,
    input   logic [8*4-1:0]         chs_weight      ,
    input   logic [8*DATA_W-1:0]    chs_data        ,
    output  logic [7:0]             chs_sel         ,
    output  logic                   data_out_vld    ,
    output  logic [DATA_W-1:0]      data_out
);

    //------------------------------------------------------------------------------    
    // struct define
    //typedef struct packed {
    //    logic                   valid   ;
    //    logic   signed [3:0]    weight  ;
    //} wrr_if_t; 
    
    
