    input   [REMAP_ADDR_W-1:0]      gp0_tx_addr_remap_mask,
    input   [REMAP_ADDR_W-1:0]      gp0_tx_addr_remap_value,
    input   [REMAP_ADDR_W-1:0]      gp0_tx_addr_src_value,
    input                           gp1_tx_addr_remap_en,
    input   [REMAP_ADDR_W-1:0]      gp1_tx_addr_remap_mask,
    input   [REMAP_ADDR_W-1:0]      gp1_tx_addr_remap_value,
    input   [REMAP_ADDR_W-1:0]      gp1_tx_addr_src_value,
    input                           gp2_tx_addr_remap_en,
    input   [REMAP_ADDR_W-1:0]      gp2_tx_addr_remap_mask,
    input   [REMAP_ADDR_W-1:0]      gp2_tx_addr_remap_value,
    input   [REMAP_ADDR_W-1:0]      gp2_tx_addr_src_value,
    input                           gp3_tx_addr_remap_en,
    input   [REMAP_ADDR_W-1:0]      gp3_tx_addr_remap_mask,
    input   [REMAP_ADDR_W-1:0]      gp3_tx_addr_remap_value,
    input   [REMAP_ADDR_W-1:0]      gp3_tx_addr_src_value,
    
    input   [REMAP_ADDR_W+19:0]     slv_awaddr_i,
    input   [REMAP_ADDR_W+19:0]     slv_araddr_i,
    input   [REMAP_ADDR_W+19:0]     slv_acaddr_i,
    output  reg [REMAP_ADDR_W+19:0] slv_awaddr_o,
    output  reg [REMAP_ADDR_W+19:0] slv_araddr_o,
    output  reg [REMAP_ADDR_W+19:0] slv_acaddr_o
);


