`ifndef __M2_IRQ_HANDLE__
`define __M2_IRQ_HANDLE__

`resetall
`timescale 1ns/1ps

module M2_irq_handle #(
  parameter CH_NUM = 17 ,
  parameter MAC_CH_NUM = 8,
  parameter SYNC_LEVEL = 2
  )
  (/*autoarg*/
   // Outputs
   pcs_rx_link_done0_isr_pclk, pcs_rx_link_done1_isr_pclk,
   mac_rx_link_done_isr_pclk, rx_lane_sram_sample_done_isr_pclk,
   phy_dcc_cal_end_isr_pclk, phy_pll_lock_isr_pclk,
   raw_pcs_bit_lock_done_isr_pclk, pcs_crc_error_isr_pclk,
   pcs_cmd_crc_error_isr_pclk, pcs_retry_timeout_isr_pclk,
   pcs_retry_id_timeout_isr_pclk,
   chs_cxs_mst_parity_error_isr_pclk,
   mac_chs_rx_fifo_overflow_isr_pclk,
   mac_chs_tx_fifo_overflow_isr_pclk,
   raw_pcs_bit_lock_fail0_data_isr_pclk,
   raw_pcs_bit_lock_fail1_isr_pclk,
   raw_pcs_bit_lock_retry_cnt_overflow_isr_pclk,
   raw_pcs_bit_lock_ber_cnt_overflow_isr_pclk,
   raw_pcs_bit_lock_ber_cnt2_overflow_isr_pclk,
   pcs_chn_crc_error_isr_pclk,
   // Inputs
   pclk, presetn, pcs_tx_clk, pcs_rx_clk, pcs_tx_rstn, pcs_rx_rstn, scan_mode, pcs_rx_link_done0,


   port0_clk, port1_clk, port2_clk, port3_clk, port4_clk, port5_clk, port6_clk, port7_clk,  
   port0_rst_n, port1_rst_n, port2_rst_n, port3_rst_n, port4_rst_n, port5_rst_n, port6_rst_n, port7_rst_n,

   pcs_rx_link_done1, mac_rx_link_done, rx_lane_sram_sample_done,
   phy_dcc_cal_end, phy_pll_lock, raw_pcs_bit_lock_done,
   pcs_crc_error, pcs_cmd_crc_error, pcs_retry_timeout, chs_cxs_mst_parity_error,
   mac_chs_rx_fifo_overflow, mac_chs_tx_fifo_overflow,
   pcs_retry_id_timeout, raw_pcs_bit_lock_fail0_data,
   raw_pcs_bit_lock_fail1, raw_pcs_bit_lock_retry_cnt_overflow,
   raw_pcs_bit_lock_ber_cnt_overflow,
   raw_pcs_bit_lock_ber_cnt2_overflow, pcs_chn_crc_error

   );

input                                   pclk;
input                                   presetn;

input                                   pcs_tx_clk;
input                                   pcs_rx_clk;
input                                   pcs_tx_rstn;
input                                   pcs_rx_rstn;




input                                   scan_mode;

input                                   port0_clk;
input                                   port1_clk;
input                                   port2_clk;
input                                   port3_clk;
input                                   port4_clk;
input                                   port5_clk;
input                                   port6_clk;
input                                   port7_clk;

input                                   port0_rst_n;
input                                   port1_rst_n;
input                                   port2_rst_n;
input                                   port3_rst_n;
input                                   port4_rst_n;
input                                   port5_rst_n;
input                                   port6_rst_n;
input                                   port7_rst_n;

// mission int status0
input                                   pcs_rx_link_done0;
input                                   pcs_rx_link_done1;
input                                   mac_rx_link_done;   // TODO : 2104 not done. will update in the furture.
input                                   rx_lane_sram_sample_done;
input                                   phy_dcc_cal_end;
input                                   phy_pll_lock;

// mission int status1
input        [CH_NUM-1:0]               raw_pcs_bit_lock_done;
// input        [15:0]                     raw_pcs_pcs_lock_done;  // TODO: not used pcs function in raw_pcs

// error int status0
input                                   pcs_crc_error;
input                                   pcs_cmd_crc_error;
input                                   pcs_retry_timeout;
input                                   pcs_retry_id_timeout;
input        [MAC_CH_NUM-1:0]           chs_cxs_mst_parity_error;
input        [MAC_CH_NUM*8-1:0]         mac_chs_rx_fifo_overflow;
input        [MAC_CH_NUM*2-1:0]         mac_chs_tx_fifo_overflow;

// error int status1
input        [CH_NUM-1:0]               raw_pcs_bit_lock_fail0_data;
// input        [15:0]                     raw_pcs_bit_lock_fail0_clk;

// error int status2
input        [CH_NUM-1:0]               raw_pcs_bit_lock_fail1;

// error int status3
input        [CH_NUM-1:0]               raw_pcs_bit_lock_retry_cnt_overflow;

// error int status4
input        [CH_NUM-1:0]               raw_pcs_bit_lock_ber_cnt_overflow;

// error int status5
input        [CH_NUM-1:0]               raw_pcs_bit_lock_ber_cnt2_overflow;

// error int status6
input        [CH_NUM-1:0]               pcs_chn_crc_error;   // TODO


// output to st_s_reg
output                                  pcs_rx_link_done0_isr_pclk;
output                                  pcs_rx_link_done1_isr_pclk;
output                                  mac_rx_link_done_isr_pclk;
output                                  rx_lane_sram_sample_done_isr_pclk;
output                                  phy_dcc_cal_end_isr_pclk;
output                                  phy_pll_lock_isr_pclk;
output        [CH_NUM-1:0]              raw_pcs_bit_lock_done_isr_pclk;

output                                  pcs_crc_error_isr_pclk;
output                                  pcs_cmd_crc_error_isr_pclk;
output                                  pcs_retry_timeout_isr_pclk;
output                                  pcs_retry_id_timeout_isr_pclk;
output        [MAC_CH_NUM-1:0]          chs_cxs_mst_parity_error_isr_pclk;
output        [MAC_CH_NUM*8-1:0]        mac_chs_rx_fifo_overflow_isr_pclk;
output        [1:0]                     mac_chs_tx_fifo_overflow_isr_pclk;

output        [CH_NUM-1:0]              raw_pcs_bit_lock_fail0_data_isr_pclk;
output        [CH_NUM-1:0]              raw_pcs_bit_lock_fail1_isr_pclk;
output        [CH_NUM-1:0]              raw_pcs_bit_lock_retry_cnt_overflow_isr_pclk;
output        [CH_NUM-1:0]              raw_pcs_bit_lock_ber_cnt_overflow_isr_pclk;
output        [CH_NUM-1:0]              raw_pcs_bit_lock_ber_cnt2_overflow_isr_pclk;
output        [CH_NUM-1:0]              pcs_chn_crc_error_isr_pclk;  // TODO

