`resetall
`timescale 1ns/1ps

module M2_apb_st_s_biu
  # (
   parameter APB_ADDR_SLICE_LHS = 16,
   parameter APB_DATA_WIDTH = 32,
   parameter MAX_APB_DATA_WIDTH = 32,
   parameter DLY = 0.1

  )
  (
   // APB bus bus interface
   pclk,
   presetn,
   psel,
   penable,
   pwrite, 
   paddr,
   pwdata,
   prdata,
   
   // regfile interface
   wr_en,
   rd_en,
   byte_en,
   reg_addr,
   ipwdata,
   iprdata

   );

  // -------------------------------------
  // -- APB bus signals
  // -------------------------------------
  input                            pclk;         // APB clock
  input                            presetn;      // APB reset
  input                            psel;         // APB slave select
  // leda NTL_CON13C off
  // LMD: Non driving port range ;
  // LJ : Last 1/2 bits of paddr will always be 0 when APB_DATA_WIDTH==16/32, due to address alignment. Hence they go unused.
  // leda NTL_CON37  off
  // LMD: Non driving port range ;
  // LJ : Last 1/2 bits of paddr will always be 0 when APB_DATA_WIDTH==16/32, due to address alignment. Hence they go unused.
  input [APB_ADDR_SLICE_LHS-1:0]  paddr;        // APB address
  // leda NTL_CON13C on
  // leda NTL_CON37  on
  input                            pwrite;       // APB write/read
  input                            penable;      // APB enable
  input [`APB_DATA_WIDTH-1:0]      pwdata;       // APB write data bus
  
  output [`APB_DATA_WIDTH-1:0]     prdata;       // APB read data bus
  
  // -------------------------------------
  // -- Register block interface signals
  // -------------------------------------
  input [`MAX_APB_DATA_WIDTH*2-1:0]    iprdata;      // Internal read data bus
  
  output [1:0]                     wr_en;        // Write enable signal
  output [1:0]                     rd_en;        // Read enable signal
  output [3:0]                     byte_en;      // Active byte lane signal
  output [APB_ADDR_SLICE_LHS-6:0]  reg_addr;     // Register address offset
  output [`MAX_APB_DATA_WIDTH*2-1:0]    ipwdata;      // Internal write data bus
  // -------------------------------------
  // -- Local registers & wires
  // -------------------------------------
  
