`resetall
`timescale 1ns/1ps

module M2_clci_ucie_s
 #(
  parameter MAC_CH_NUM          = 8,
  parameter CH_NUM              = 18,
  parameter DATA_CH_NUM         = 16,
  parameter REDUND_CH_NUM       = 2,
  parameter APB_ADDR_SLICE_LHS  = 16,
  parameter MAX_APB_DATA_WIDTH  = 32,
  parameter CXS_MAX_CREDIT      = 4,
  parameter CXS_MAX_CREDIT_LATENCY = 2,
  parameter DLY                 = 1,
  parameter DLY_LINE_WIDTH      = 8,
  parameter REDUND_TIE          = 1'b0,
  parameter PCS_DATA_WIDTH      = 20,

  parameter MCU_REBOOT_SRC      = 32'h0000_0000,
  parameter MCU_VENDOR_ID       = 16'h00AB,
  parameter MCU_REVISION_ID     = 16'h2511,
  parameter MCU_DEVICE_ID       = 32'h2,
  parameter MCU_I2C_DEV_ID      = 8'hAC,
  parameter SB_MAX_CREDIT       = 4,
  parameter ACE_HAS_MASTER      = 1,
  parameter ACE_HAS_SLAVE       = 1,
  parameter ACE_DW              = 128,
  parameter CHI_HAS_MASTER      = 1,
  parameter CHI_HAS_SLAVE       = 1,
  parameter CXS_PIPE_LVL        = 0,
  parameter AXI_OST_CAPABILITY  = 128,
  parameter AXI_RX_DATA_DEPTH   = 8,
  parameter SYNC_LEVEL          = `SYNCHNRONIZER_LEVEL
 )
 (
  // apb interface
  input                         pclk,         // apb peripheral clock, max 200MHz 
  input                         presetn,

  // irq
  output                        dbg_irq,

  //input                         mcu_clk,      // mcu high speed clock, max 800MHz 
  //input                         mcu_rstn,     // resetn sync to mcu_clk
  // input                         clci_clk,
  input                         top_pll_800mhz, // for sideband serial clock
  // input                         clci_rstn,
  input                         clci_mode_sel,  //0:stream_mode, 1:normal mode

  //------------------------------ MCU ------------------------------
  input     [1:0]               boot_sel,       // stap pin for boot software 
  input     [3:0]               strapping_mode, 
  input     [26:0]              gpio_in_sideband,     // sideband interrupt input to remote-die
  //output    [26:0]              gpio_ack_sideband,    // sideband interrupt input acknowledge
  output    [26:0]              gpio_out_sideband,    // sideband interrupt output from remote-die
  input     [7:0]               chiplet_id,
  input                         i2c_id_vld,     
  input     [6:0]               i2c_id,         // replace MCU_I2C_DEV_ID[7:1] when i2c_id_vld = 1
  input                         mcu_wdt_sim_speed,
  input     [31:0]              mcu_id,               // provide version tag id for mcu, recommend tie 0;
  input     [31:0]              mcu_jtag_id,          // provide jtag_id to identify which jtag used in soc;
  input                         mcu_tck,
  input                         mcu_tms,
  input                         mcu_tdi,
  input                         mcu_trst_n,
  output                        mcu_tdo,
  output                        mcu_tdo_en,
  input                         mcu_uart_rx0,
  output                        mcu_uart_tx0,
  input                         mcu_uart_rx1,
  output                        mcu_uart_tx1,
  input                         mcu_scl_in,
  input                         mcu_sda_in,
  output                        mcu_sda_oe_n,
  output                        mcu_db2soc_irq,

  input                         soc_i_pclk,
  input                         soc_i_presetn,
  input                         soc_i_psel,
  input                         soc_i_penable,
  input                         soc_i_pwrite,
  input     [17:0]              soc_i_paddr,
  input     [31:0]              soc_i_pwdata,
  output                        soc_i_pready,
  output    [31:0]              soc_i_prdata,
  output                        soc_i_pslverr,

`ifdef FPGA
  input                         sb_m_pready,
  input   [31:0]                sb_m_prdata,
  output                        sb_m_psel,
  output                        sb_m_penable,
  output                        sb_m_pwrite,
  output  [23:0]                sb_m_paddr,
  output  [31:0]                sb_m_pwdata,
`endif


//------------------------ CHI request node ------------------------
//----------------------------- port0 ------------------------------


  
  
  
  
  // ace port 2
  input                           ace_2_rst_n,
  input                           ace_2_clk,
  
  output                          ace_slv2_awready,
  input                           ace_slv2_awvalid,
  input   [15:0]                  ace_slv2_awid,
  input   [43:0]                  ace_slv2_awaddr,
  input   [7:0]                   ace_slv2_awlen,
  input   [2:0]                   ace_slv2_awsize,
  input   [1:0]                   ace_slv2_awburst,
  input   [3:0]                   ace_slv2_awregion,
  input                           ace_slv2_awlock,
  input   [3:0]                   ace_slv2_awcache,
  input   [2:0]                   ace_slv2_awprot,
  input   [3:0]                   ace_slv2_awqos,
  input   [2:0]                   ace_slv2_awsnoop,
  input   [1:0]                   ace_slv2_awdomain,
  input   [1:0]                   ace_slv2_awbar,
  input                           ace_slv2_awunique,
  
  output                          ace_slv2_arready,
  input                           ace_slv2_arvalid,
  input   [15:0]                  ace_slv2_arid,
  input   [43:0]                  ace_slv2_araddr,
  input   [7:0]                   ace_slv2_arlen,
  input   [2:0]                   ace_slv2_arsize,
  input   [1:0]                   ace_slv2_arburst,
  input   [3:0]                   ace_slv2_arregion,
  input                           ace_slv2_arlock,
  input   [3:0]                   ace_slv2_arcache,
  input   [2:0]                   ace_slv2_arprot,
  input   [3:0]                   ace_slv2_arqos,
  input   [3:0]                   ace_slv2_arsnoop,
  input   [1:0]                   ace_slv2_ardomain,
  input   [1:0]                   ace_slv2_arbar,
  
  output                          ace_slv2_crready,
  input                           ace_slv2_crvalid,
  input   [4:0]                   ace_slv2_crresp,
  
  output                          ace_slv2_wready,
  input                           ace_slv2_wvalid,
  input   [ACE_DW-1:0]            ace_slv2_wdata,
  input   [(ACE_DW/8)-1:0]        ace_slv2_wstrb,
  input                           ace_slv2_wlast,
  
  output                          ace_slv2_cdready,
  input                           ace_slv2_cdvalid,
  input   [ACE_DW-1:0]            ace_slv2_cddata,
  input                           ace_slv2_cdlast,
  
  output                          ace_mst2_bready,
  input                           ace_mst2_bvalid,
  input   [15:0]                  ace_mst2_bid,
  input   [1:0]                   ace_mst2_bresp,
  
  output                          ace_mst2_acready,
  input                           ace_mst2_acvalid,
  input   [14:0]                  ace_mst2_acvid,
  input   [43:0]                  ace_mst2_acaddr,
  input   [3:0]                   ace_mst2_acsnoop,
  input   [2:0]                   ace_mst2_acprot,
  
  output                          ace_mst2_rready,
  input                           ace_mst2_rvalid,
  input   [15:0]                  ace_mst2_rid,
  input   [ACE_DW-1:0]            ace_mst2_rdata,
  input   [3:0]                   ace_mst2_rresp,
  input                           ace_mst2_rlast,
  
  input                           ace_slv2_wack,
  input                           ace_slv2_rack,
  
  input                           ace_mst2_awready,
  output                          ace_mst2_awvalid,
  output  [15:0]                  ace_mst2_awid,
  output  [43:0]                  ace_mst2_awaddr,
  output  [7:0]                   ace_mst2_awlen,
  output  [2:0]                   ace_mst2_awsize,
  output  [1:0]                   ace_mst2_awburst,
  output  [3:0]                   ace_mst2_awregion,
  output                          ace_mst2_awlock,
  output  [3:0]                   ace_mst2_awcache,
  output  [2:0]                   ace_mst2_awprot,
  output  [3:0]                   ace_mst2_awqos,
  output  [2:0]                   ace_mst2_awsnoop,
  output  [1:0]                   ace_mst2_awdomain,
  output  [1:0]                   ace_mst2_awbar,
  output                          ace_mst2_awunique,
  
  input                           ace_mst2_arready,
  output                          ace_mst2_arvalid,
  output  [15:0]                  ace_mst2_arid,
  output  [43:0]                  ace_mst2_araddr,
  output  [7:0]                   ace_mst2_arlen,
  output  [2:0]                   ace_mst2_arsize,
  output  [1:0]                   ace_mst2_arburst,
  output  [3:0]                   ace_mst2_arregion,
  output                          ace_mst2_arlock,
  output  [3:0]                   ace_mst2_arcache,
  output  [2:0]                   ace_mst2_arprot,
  output  [3:0]                   ace_mst2_arqos,
  output  [3:0]                   ace_mst2_arsnoop,
  output  [1:0]                   ace_mst2_ardomain,
  output  [1:0]                   ace_mst2_arbar,
  
  input                           ace_mst2_crready,
  output                          ace_mst2_crvalid,
  output  [4:0]                   ace_mst2_crresp,
  
  input                           ace_mst2_wready,
  output                          ace_mst2_wvalid,
  output  [ACE_DW-1:0]            ace_mst2_wdata,
  output  [(ACE_DW/8)-1:0]        ace_mst2_wstrb,
  output                          ace_mst2_wlast,
  
  input                           ace_mst2_cdready,
  output                          ace_mst2_cdvalid,
  output  [ACE_DW-1:0]            ace_mst2_cddata,
  output                          ace_mst2_cdlast,
  
  input                           ace_slv2_bready,
  output                          ace_slv2_bvalid,
  output  [15:0]                  ace_slv2_bid,
  output  [1:0]                   ace_slv2_bresp,
  
  input                           ace_slv2_acready,
  output                          ace_slv2_acvalid,
  output  [14:0]                  ace_slv2_acvid,
  output  [43:0]                  ace_slv2_acaddr,
  output  [3:0]                   ace_slv2_acsnoop,
  output  [2:0]                   ace_slv2_acprot,
  
  input                           ace_slv2_rready,
  output                          ace_slv2_rvalid,
  output  [15:0]                  ace_slv2_rid,
  output  [ACE_DW-1:0]            ace_slv2_rdata,
  output  [3:0]                   ace_slv2_rresp,
  output                          ace_slv2_rlast,
  
  output                          ace_mst2_wack,
  output                          ace_mst2_rack,
  
  //------------------------ sideband -------------------------
  //----------------- should sync up with pcs clk -------------
  input   [7:0]                   sideband_dat,
  output  [7:0]                   otherside_sideband_dat,



  //  system related
  input                   reset_n,  // equal to clci_rstn ?
  //input                   normal_mode,
  input                   test_mode,
  // input                   scan_mode,
  input                   scan_en,
  // input                   pll_bypass,
  // input                   icg_mode,
  // input                   mbist_mode,

  // input                   scan_clk_aclk,
  // input                   scan_clk_pclk,
  input                   scan_clk_20,
  input                   scan_clk_20_tx,
  input                   scan_clk_20_rx,
  input                   scan_clk_80,
  // input                   scan_clk_66,

  // output [CH_NUM-1:0]     irq_n,
  output [CH_NUM-1:0]     clci_st_s_bist_correct_clk,


//----------------------------------------- MACSIM -----------------------------------------

  input                           ref_clk,
  input                           syn_pll_in,
  output                          pll2dig_clk,
  output                          pmd_div20_clk_out,
  output                          pcs_tx_clk_scan_out,
  output                          pcs_rx_clk_scan_out,

//  output                          aclk_tx_gated,
//  output                          aclk_rx_gated,

  // irq
//  output                          mission_irq,
//  output                          error_irq,
//`ifndef SINGLEPHY
//  output                          mission_irq1,
//  output                          error_irq1,
//`endif

`ifdef FPGA
  input                           aclk_tx,
  input                           aclk_rx,
  input                           aclk_div4_tx,
  input                           aclk_div4_rx,
  input  [CH_NUM*40-1:0]          pmd_rx_data40,
  output [CH_NUM*40-1:0]          pmd_tx_data40,
`endif



  // voltage monitor
  inout                           vmon_clci_phy_avdd_st_0,
  inout                           vmon_clci_phy_avdd_st_ck_0,
  inout                           vmon_clci_phy_avss_st_0,
  inout                           vmon_clci_phy_avss_st_ck_0,
  inout                           vmon_clci_phy_avdd_st_1,
  inout                           vmon_clci_phy_avdd_st_ck_1,
  inout                           vmon_clci_phy_avss_st_1,
  inout                           vmon_clci_phy_avss_st_ck_1,

//---------------------------------------------------------------------------------------
  
  // to BUMP
  output                          TXCKSB,
  output                          TXDATASB,
  input                           RXCKSB,
  input                           RXDATASB,
  
  output [DATA_CH_NUM-1:0]        TX_D,
  output                          TX_VLD,
  output                          TX_TRK,
  output                          TX_CLK_P,
  output                          TX_CLK_N,
  input [DATA_CH_NUM-1:0]         RX_D,
  input                           RX_VLD,
  input                           RX_TRK,
  input                           RX_CLK_P,
  input                           RX_CLK_N,
  input                           EXT_CLK_P,
  input                           EXT_CLK_N




