`timescale 1ns/1ps    
                      
module  M2_clk_rst_gen #(
        parameter                      SYNC_LEVEL = 2
 )
 (
    // clock ports  
    // input           aclk,
    input           pclk,
    input           mac_mon_rstn,
    input           stream_mode,


    input           ace_2_clk      , // 
    output          ace_2_clk_scan , // 






    input           scan_clk_20,
    // input           scan_clk_aclk,
    input           scan_clk_pclk,
    input           icg_mode,
    input           mbist_mode,
    input           scan_mode,
    // input           pll_bypass,
    input           pcs_legacy_clk_mode,
    input           pcs_tx_clk,
    input           pcs_rx_clk,
    // input           pmd_txfifo_wr_afull_pipe2_out,
    // input           pmd_rxfifo_rd_aempty_pipe2_out,
    // output          aclk_tx_gated,
    // output          aclk_rx_gated,
    output          pcs_tx_clk_scan,
    output          pcs_rx_clk_scan,
    // output          aclk_scan,
    output          pclk_scan,

    // reset ports
    input           reset_n,
    input           mac_pcs_reset,
    input           sphy0_reset,
    input           ref_clk,
    output          ref_rstn,


    input           ace_2_rst_n,
    output          ace_2_srstn,



    output          sphy0_aresetn,
    output          tx_clk_rstn,
    output          rx_clk_rstn
);

    
