        parameter                      SYNC_LEVEL = 2
        )
(
    input       reset_n,
    input       mac_pcs_reset,
    input       sphy0_reset,
    // input       aclk,
    input       mac_mon_rstn,
    input       ref_clk,
    output      ref_rstn,

    input       ace_2_rst_n,
    input       ace_2_clk,
    output      ace_2_srstn,

    input       pcs_tx_clk_scan,
    input       pcs_rx_clk_scan,
    output      tx_clk_rstn,
    output      rx_clk_rstn,
    output      sphy0_aresetn, // to sphy0 reset_n
    input       scan_mode

);

