`timescale 1 ns/1 ps

module M2_clci_sig_syncup # ( parameter
    SYNC_LEVEL = 2
    ) (
        input                       scan_mode,
        input                       pclk,
        input                       presetn,

//--------------------- pcs0 clk  -------------------------
        input                       aclk_rx_gated,
        input                       aclk_tx_gated,
        input                       rx_clk_rstn,
        input                       tx_clk_rstn,

//---------------------- chi0 clk -------------------------
        input                       chi_0_clk,
        input                       chi_0_rst_n,

//---------------------- axis1 clk ------------------------
        input                       axis_1_clk,
        input                       axis_1_rst_n,

//---------------------- ace2 clk -------------------------
        input                       ace_2_clk,
        input                       ace_2_rst_n,

//---------------------- axi4 clk -------------------------
        input                       axi_4_clk,
        input                       axi_4_rst_n,

//---------------------- streams416 clk -------------------------
        input                       streams416_4_clk,
        input                       streams416_4_rst_n,

//---------------------- axi5 clk -------------------------
        input                       axi_5_clk,
        input                       axi_5_rst_n,

//---------------------- streams704 clk -------------------------
        input                       streams704_56_clk,
        input                       streams704_56_rst_n,

//---------------------- axi5 clk -------------------------
        input                       cxs_7_clk,
        input                       cxs_7_rst_n,

//---------------------------------------------------------
        input                       legacy_mode,
        input   [1:0]               flow_ctrl_src,

        input   [1:0]               rx_link_status,
//        input   [23:0]              pcs0_rx_buf_status,
        input   [1:0]               pcs0_link_delay_cnt,
        input                       pcs0_port0_rx_afifo_afull,
        input                       pcs0_port1_rx_afifo_afull,
        input                       axis_mst1_rx_fifo_afull,
        input                       pcs0_port2_rx_afifo_afull,
        input                       pcs0_port3_rx_afifo_afull,
        input                       pcs0_port4_rx_afifo_afull,
        input                       pcs0_port5_rx_afifo_afull,
        input                       pcs0_port6_rx_afifo_afull,
        input                       pcs0_port7_rx_afifo_afull,
        output                      mac_rx_link_done,
        input   [23:0]              pcs0_otherside_rx_buf_status,
        output                      axis_slv1_otherside_rx_fifo_afull,
        output                      chi_0_otherside_wr_full_otherside,
        output                      chi_0_otherside_mac_rx_full_otherside,
        output                      ace_slv2_otherside_rx_wd_full,
        output                      ace_slv2_otherside_rx_rd_full,
        output                      ace_slv2_otherside_rx_cd_full,
        output                      port2_pcs0_wr_full_otherside,
        output                      port4_pcs0_wr_full_otherside,
        output                      axi_slv4_otherside_rx_wr_full,
        output  [23:0]              pcs0_rx_buf_status_tx_domain,
        output                      port1_pcs0_wr_full_otherside,
        output                      port3_pcs0_wr_full_otherside,
        output                      port7_pcs0_wr_full_otherside,
        input                       pcs_cmd_crc_error,
        input                       pcs0_otherside_rx_buf_vld,
        output                      pcs0_port2_tx_pause,
        output                      pcs0_port4_tx_pause,
        output                      pcs0_port5_tx_pause,
        output                      pcs0_port7_tx_pause,
        // axi firewall 
        input                       glob_irpt_en_ctl_pclk, 
        input                       unblock_ctl_mi_pclk, 
        input                       unblock_ctl_si_pclk, 
        output                      mi_w_error_pclk, 
        output                      mi_r_error_pclk, 
        output                      si_w_error_pclk, 
        output                      si_r_error_pclk, 
        output                      ip2intc_irpt_mi_pclk, 
        output                      ip2intc_irpt_si_pclk, 

        input                       mi_w_error, 
        input                       mi_r_error, 
        input                       si_w_error, 
        input                       si_r_error, 
        input                       ip2intc_irpt_mi, 
        input                       ip2intc_irpt_si, 
        output                      glob_irpt_en_ctl, 
        output                      unblock_ctl_mi, 
        output                      unblock_ctl_si, 

        input                       port0_pcs0_mac_rx_buf_full,
        input                       ace_mst2_rx_wd_afull,
        input                       ace_mst2_rx_rd_afull,
        input                       ace_mst2_rx_cd_afull,
        input                       axi_mst4_rx_fifo_afull,
        input                       axi_mst4_rx_fifo2_afull,
        input                       cxs_mst7_rx_fifo_afull,
        input                       axi_mst5_rx_fifo_afull,
        input                       axi_mst5_rx_fifo2_afull,
        input                       pcs_retry_cnt_clear,
        output                      pcs_retry_cnt_clear_reg,
        input   [7:0]               sideband_dat,
        output  [7:0]               otherside_sideband_dat,
        output                      axi_slv4_otherside_rx_rd_full,
        output                      port5_pcs0_wr_full_otherside,
        output                      port6_pcs0_wr_full_otherside,
        output                      axi_slv5_otherside_rx_fifo_afull,
        output                      axi_slv5_otherside_rx_fifo2_afull,
        output                      cxs_slv7_otherside_rx_fifo_afull

        );


