`ifndef M2_CL2301_SYNC_FIFO_MODULE
`define M2_CL2301_SYNC_FIFO_MODULE

`resetall
`timescale 10 ps/10 ps

//-----------------------------------------------------
// Function    : Synchronous (single clock) FIFO
//-----------------------------------------------------
module M2_cl2301_sync_fifo # (
// FIFO constants
parameter DATA_WIDTH = 32,
parameter ADDR_WIDTH = 2,
parameter FULL_TH    = 4,
parameter FIFO_DEPTH = (1 << ADDR_WIDTH),
parameter FULL_WR_EN = 0,
parameter DELAY = 0
) (
input clk      , // Clock input
input rst_n    , // Active low reset
input [DATA_WIDTH-1:0] data_in  , // Data input
input rd_en    , // Read enable
input wr_en    , // Write Enable
output [DATA_WIDTH-1:0] data_out , // Data Output
output reg empty    , // FIFO empty
output reg full     , // FIFO full
output full_almost  ,
output reg [ADDR_WIDTH :0] rd_status_cnt, // Count for read entries\
output reg [ADDR_WIDTH :0] wr_status_cnt
);


