`ifndef M2_CL2301_ASYNC_FIFO_MODULE
`define M2_CL2301_ASYNC_FIFO_MODULE

module M2_cl2301_async_fifo #(
parameter WIDTH = 32,       // Actual bit width of the FIFO
parameter DEPTH = 4,        // power of 2 depth of the FIFO
parameter WR_EN_NUM = 1,
parameter  DELAY = 0,
parameter  SYNC_LEVEL = 2
)  (
   rd_clk,                  // read domain clock
   rd_inc,                  // read pointer increment
   rd_rst_x,                // read domain reset
   ptest_scan_mode,               // test mode input
   wr_clk,                  // write domain clock
   wr_data,                 // write data
   wr_en,                   // write enable (byte wise)
   wr_inc,                  // write pointer increment
   wr_rst_x,                // write domain reset
   wr_thresh,               // write threshold for almost empty detection
  
   rd_data,
   r_rd_empty,         // read domain empty register output
   rd_empty,           // read domain empty combinational output almost empty
   w_wr_afull,
   wr_full,             // write full combinatorial
   wr_avail_entry
   );
input                  rd_clk;           // read domain clock
input                  rd_inc;           // read increment
input                  rd_rst_x;         // read domain reset
input                  ptest_scan_mode;        // scan test mode
input                  wr_clk;           // write domain clock
input [WIDTH-1:0]      wr_data;          // write data
input [WR_EN_NUM-1:0]  wr_en;            // write enable
input                  wr_inc;           // write increment
input                  wr_rst_x;         // asynchronous reset
input [DEPTH-1:0]      wr_thresh;        // write threshold (wr_afull support)

// outputs (alphabetized)
output  reg           w_wr_afull;  //
output                wr_full;  // write full combinatorial
output             r_rd_empty;  // read domain empty registered
output              rd_empty;
output [WIDTH-1:0] rd_data;     // read data
output [DEPTH:0]   wr_avail_entry;
//wire [DEPTH:0]   wr_avail_entry;


