`ifndef __M2_CLCI_SIDEBAND_TOP__
`define __M2_CLCI_SIDEBAND_TOP__

`resetall
`timescale 1ns/1ps

module M2_clci_sideband_top #(
  parameter SYNC_LEVEL = 2,
  parameter SB_MAX_CREDIT = 4,
  parameter VENDOR_ID = 16'h2503
)(  
    input                           presetn,
    input                           pclk,
    input                           top_pll_800mhz,
    input                           aphy_pll_div2_rx,
    input                           aphy_pll_div2_tx,
    input       [1:0]               sb_tx_sclk_mux_sel,
    input                           strapping_init,
    input                           gpio_trans_enable,
    input       [26:0]              gpio_in_sideband,
    output      [26:0]              gpio_in_sideband_ack,
    output      [26:0]              gpio_out_sideband,
    input       [15:0]              sb_gpio_trig_gap,
    input                           sb_init_8ms_en,
    input                           sb_init_start,
    input                           sb_force_init_done,
    input                           sb_ctrl_rstn,
    output      [3:0]               sb_tx_p2s_state_debug,
    output      [3:0]               sb_init_state_debug,
    output                          sb_init_done,
    output                          sb_train_error,
    output      [3:0]               sb_init_done_debug,
    input                           sb_pmo_mode,
    input                           sb_rx_phase_sel,
    input                           sb_loopback_mode,
    input       [3:0]               sb_tx_init_rd_sel,
    input                           sb_link_if_debug_en, 
    output                          sb_link_debug_tx_rdy,
    input                           sb_link_debug_tx_vld,
    input       [31:0]              sb_link_debug_tx_data,
    input                           sb_link_debug_rx_irdy,
    output                          sb_link_debug_rx_rdy,
    output                          sb_link_debug_rx_vld,
    output      [31:0]              sb_link_debug_rx_data,
    input                           sb_rdi_if_debug_en, 
    output                          sb_rdi_debug_tx_rdy,
    input                           sb_rdi_debug_tx_vld,
    input       [31:0]              sb_rdi_debug_tx_data,
    input                           sb_rdi_debug_rx_irdy,
    output                          sb_rdi_debug_rx_rdy,
    output                          sb_rdi_debug_rx_vld,
    output      [31:0]              sb_rdi_debug_rx_data,
    input                           sb_fdi_if_debug_en,
    input                           sb_fdi_debug_tx_vld,
    input       [31:0]              sb_fdi_debug_tx_data,
    output                          sb_fdi_debug_tx_rdy,
    input                           sb_fdi_debug_rx_irdy,
    output                          sb_fdi_debug_rx_vld,
    output      [31:0]              sb_fdi_debug_rx_data,
    output                          sb_fdi_debug_rx_rdy,
    output                          sb_rdi_tx_cp_err,
    output                          sb_rdi_tx_dp_err,
    output      [4:0]               sb_rdi_tx_credit,
    output                          sb_rdi_rx_cp_err,
    output                          sb_rdi_rx_dp_err,
    output      [4:0]               sb_rdi_rx_credit,
    output                          sb_fdi_tx_cp_err,
    output                          sb_fdi_tx_dp_err,
    output      [4:0]               sb_fdi_tx_credit,
    output                          sb_fdi_rx_cp_err,
    output                          sb_fdi_rx_dp_err,
    output      [4:0]               sb_fdi_rx_credit,
    input       [31:0]              sb_cmpl_timeout_cnt,
    output                          adapter_cmpl_timeout, 
    output      reg                 sb_tx_credit_runout,
     
    input                           rt_m_aresetn,
    input                           rt_m_aclk,
    input                           rt_m_awready,
    output                          rt_m_awvalid,
    output      [3:0]               rt_m_awid,
    output      [31:0]              rt_m_awaddr,
    output      [7:0]               rt_m_awlen,
    output      [2:0]               rt_m_awsize,
    output      [1:0]               rt_m_awburst,
    output      [3:0]               rt_m_awregion,
    output                          rt_m_awlock,
    output      [3:0]               rt_m_awcache,
    output      [2:0]               rt_m_awprot,
    output      [3:0]               rt_m_awqos,
    input                           rt_m_wready,
    output                          rt_m_wvalid,
    output      [63:0]              rt_m_wdata,
    output      [7:0]               rt_m_wstrb,
    output                          rt_m_wlast,
    output                          rt_m_bready,
    input                           rt_m_bvalid,
    input       [3:0]               rt_m_bid,
    input       [1:0]               rt_m_bresp,
    input                           rt_m_arready,
    output                          rt_m_arvalid,
    output      [3:0]               rt_m_arid,
    output      [31:0]              rt_m_araddr,
    output      [7:0]               rt_m_arlen,
    output      [2:0]               rt_m_arsize,
    output      [1:0]               rt_m_arburst,
    output      [3:0]               rt_m_arregion,
    output                          rt_m_arlock,
    output      [3:0]               rt_m_arcache,
    output      [2:0]               rt_m_arprot,
    output      [3:0]               rt_m_arqos,
    output                          rt_m_rready,
    input                           rt_m_rvalid,
    input       [3:0]               rt_m_rid,
    input       [63:0]              rt_m_rdata,
    input       [1:0]               rt_m_rresp,
    input                           rt_m_rlast,

    input                           fdi_rst_n,
    input                           fdi_clk,
//    input                           sb_app_tx_vld,
//    input       [31:0]              sb_app_tx_data,
//    output                          sb_app_tx_rdy,
//    input                           sb_app_rx_irdy,
//    output                          sb_app_rx_vld,
//    output      [31:0]              sb_app_rx_data,
//    output                          sb_app_rx_rdy,
    
    input                           sb_uart_tx0,
    output                          sb_uart_rx0,
    input                           sb_uart_tx1,
    output                          sb_uart_rx1,
    input                           scan_mode,
    input                           ref_rstn,
    input                           ref_clk,

    input                           sb_io_mode, 
    input                           sb_rxdata_loop_en, 
    input                           sb_rxck_loop_en, 
    input   [3:0]                   sb_rxdata_ctrl_rt, 
    input   [3:0]                   sb_rxck_ctrl_rt, 
    input                           sb_rxdata_enable, 
    input                           sb_rxck_enable, 
    input                           sb_txdata_enable, 
    input                           sb_txck_enable, 
    input   [3:0]                   sb_rxdata_delaycode, 
    input   [3:0]                   sb_rxck_delaycode, 
    input   [8:0]                   sb_rxdata_test, 
    input   [8:0]                   sb_rxck_test, 
    input   [6:0]                   sb_txdata_test, 
    input   [6:0]                   sb_txck_test, 
    inout                           phy_ana_test,
    inout                           phy_vref_in,

    input                           RXCKSB,
    input                           RXDATASB,
    output                          TXCKSB,
    output                          TXDATASB


);


