`timescale 1ns/1ps  

module M2_sb_init_ctrl (
    input                   aux_rstn            ,
    input                   aux_sclk            ,
    input                   strapping_init      ,
    input                   sb_force_init_done  , // debug force init done, pulse
    input                   sb_init_8ms_en      , // enable init 8ms toggle mechanism
    input                   sb_cfg_init_start   , // sideband rx init start from reg
    input                   sb_train_rx_vld0    , // sideband rx data valid
    input   [63:0]          sb_train_rx_data0   , // sideband rx data
    input                   sb_train_rx_vld1    , // sideband rx data valid
    input   [63:0]          sb_train_rx_data1   , // sideband rx data
    input                   sb_train_rx_vld2    , // sideband rx data valid
    input   [63:0]          sb_train_rx_data2   , // sideband rx data
    input                   sb_train_rx_vld3    , // sideband rx data valid
    input   [63:0]          sb_train_rx_data3   , // sideband rx data
    output  reg             sb_train_error      , // sideband init fail
    output  [3:0]           sb_init_state       , // sideband initialization state
    output  reg [3:0]       sb_cfg_init_done_rd , // sideband init complete
    output                  sb_train_tx_vld     , // sb train 64b data valid
    output  reg [63:0]      sb_train_tx_data      // sb train 64b data 

);

//==============================================================================    

