`timescale 1ns/1ps  

module  M2_sideband_link_phy  #(
  parameter SYNC_LEVEL = 2
) (
    input                   lrstn                   ,
    input                   lclk                    ,
    input                   lp_cfg_vld              ,
    input   [31:0]          lp_cfg                  ,
    input                   lp_cfg_crd              ,
    output  reg             pl_cfg_vld              ,
    output  [31:0]          pl_cfg                  ,
    output                  pl_cfg_crd              ,
    
    input                   strapping_init          , // sideband init ctrl select
    input                   sb_force_init_done      ,
    input                   sb_init_8ms_en          ,
    input                   sb_cfg_init_start       , // multi-cycle pulse
    output                  sb_train_error          , // sb train failed
    output                  sb_cfg_init_done        , // sync-to aux_sclk
    output  [3:0]           sb_cfg_init_done_debug  ,
    output  [3:0]           sb_init_state_debug     , // sync-to aux_sclk
    output                  sb_lphy_tx_afull        , // sync-to lclk
    output                  sb_lphy_rx_empty        , // sync-to lclk
    input                   sb_pmo_mode             , // quasi-static
    input                   sb_rx_phase_sel         , // quasi-static
    input                   sb_loopback_mode        , // quasi-static
    input   [3:0]           sb_tx_init_rd_sel       , // quasi-static

    input                   sb_lphy_rstn            , // assert > 1us
    input                   aux_sclk                ,
    input                   sb_rx_sclk_gate         , // from sb rx ana
    input                   sb_rx_sbit              , // from sb rx ana
    output  reg             sb_tx_sclk_gate         , // to sb tx ana
    output  reg             sb_tx_sbit              , // to sb tx ana
    input                   sb_rx_sclk_gate_rd      , // from sb rx ana
    input                   sb_rx_sbit_rd           , // from sb rx ana
    output  reg             sb_tx_sclk_gate_rd      , // to sb tx ana
    output  reg             sb_tx_sbit_rd           , // to sb tx ana
    input                   scan_mode

);

//==============================================================================    

