`timescale 1ns/1ps  

module  M2_sb_physical_layer #(
    parameter   MAX_CREDIT = 8
)(
    input               lrstn               ,
    input               lclk                ,
    
    input               sb_rdi_if_en        ,
    input               sb_rdi_tx_vld       ,
    input   [31:0]      sb_rdi_tx_data      ,
    output              sb_rdi_tx_rdy       , 
    input               sb_rdi_rx_irdy      ,
    output              sb_rdi_rx_vld       ,
    output  [31:0]      sb_rdi_rx_data      ,
    output              sb_rdi_rx_rdy       ,
    output              sb_rdi_tx_cp_err    ,
    output              sb_rdi_tx_dp_err    ,
    output  [4:0]       sb_rdi_tx_credit    ,
    output              sb_rdi_rx_cp_err    ,
    output              sb_rdi_rx_dp_err    ,
    output  [4:0]       sb_rdi_rx_credit    ,

    input               rdi_lp_cfg_vld      ,
    input   [31:0]      rdi_lp_cfg          ,
    input               rdi_lp_cfg_crd      ,
    output              rdi_pl_cfg_vld      ,
    output  [31:0]      rdi_pl_cfg          ,
    output              rdi_pl_cfg_crd      ,
    
    output              link_lp_cfg_vld     ,
    output  [31:0]      link_lp_cfg         ,
    output              link_lp_cfg_crd     ,
    input               link_pl_cfg_vld     ,
    input   [31:0]      link_pl_cfg         ,
    input               link_pl_cfg_crd     
    
);

