    input   [31:0]              rdi_rx_lmem_wdata,
    input   [7:0]               rdi_rx_lmem_be,
    output  logic [31:0]        rdi_rx_lmem_rdata,
    input   [2:0]               rdi_lcmpl_status,
    input                       mailbox_req_rdy,
    output  logic               mailbox_req_vld,
    output  logic [127:0]       mailbox_req_data,
    input   [31:0]              sb_cmpl_timeout_cnt,
    input                       ref_clk, // for timer, typically 25MHz
    input                       ref_rstn,
    output  logic               timeout_err

);

