`timescale 1ns/1ps  

module  M2_sb_rx_node #(
    parameter   SB_LAYER = "PHYSICAL",
    parameter   MAX_CREDIT = 8
)(
    input                       lrstn               ,
    input                       lclk                ,

    input                       i_pl_cfg_vld        , // from lower layer p2l if
    input   [31:0]              i_pl_cfg            ,
    input                       i_lp_cfg_crd        ,
    output  logic               i_pl_cfg_rdy        , // only exist in physical
    input                       tr_local_cmpl_vld   , // local completion back
    input   [127:0]             tr_local_cmpl_data  ,
    output  logic               tr_local_cmpl_rdy   ,

    input                       sb_node_debug_en    ,
    input                       sb_debug_rx_irdy    , // debug rx if
    output  logic               sb_debug_rx_vld     ,
    output  logic [31:0]        sb_debug_rx_data    ,
    output  logic               sb_debug_rx_rdy     , // for interrupt or poll
    output  logic               o_pl_cfg_vld        , // to upper layer p2l if
    output  logic [31:0]        o_pl_cfg            ,
    output  logic               o_lp_cfg_crd        ,
    output  logic               cp_err              ,
    output  logic               dp_err              ,
    output  logic               remote_cr_vld       ,
    output  logic [2:0]         remote_cr           , // to tx_node remote credit       

    output  logic               cmpl_tag_rd         , // for cmpl compare
    output  logic [4:0]         cmpl_tag            ,
    input   [9:0]               cmpl_tag_info       ,

    output  logic               lmem_cm             , // config or memory access 
    output  logic               lmem_ce             , // request or completion consume 
    output  logic [2:0]         lmem_size           , // 32b/64b
    output  logic [11:0]        lmem_rsvd_ext       , // high 12-bits addr for lmem access
    output  logic [23:0]        lmem_addr           ,
    output  logic               lmem_we             ,
    output  logic [7:0]         lmem_be             ,
    output  logic [63:0]        lmem_wdata          ,
    input                       lmem_wvld           ,
    input                       lmem_resp           ,
    input                       lmem_rvld           , 
    input   [63:0]              lmem_rdata          , 
    output  logic               lmsg_vld            , // local message if
    output  logic [7:0]         lmsg_code           ,
    output  logic [7:0]         lmsg_subcode        ,
    output  logic [15:0]        lmsg_info           ,
    output  logic [63:0]        lmsg_data           ,
    output  logic [26:0]        lmsg_gpio           ,
    output  logic               lcmpl_vld           ,
    output  logic [2:0]         lcmpl_status        , // local cmpl record 
    output  logic [4:0]         lcmpl_tag           ,  
    input                       rt_local_req_rdy    , // remote req -> local req to physical
    output  logic               rt_local_req_vld    ,
    output  logic [127:0]       rt_local_req_data   , // need to do tag remap
    input                       rt_remote_cmpl_rdy  , // remote req -> remote cmpl to tx node
    output  logic               rt_remote_cmpl_vld  ,
    output  logic [127:0]       rt_remote_cmpl_data ,
    output  logic [4:0]         rx_node_credit

);

//==============================================================================  
//==============================================================================    

