`timescale 1ns/1ps  

module  M2_sb_tx_node #(
    parameter   SB_LAYER = "PHYSICAL",
    parameter   MAX_CREDIT = 8
)(
    input                       lrstn               ,
    input                       lclk                , // typically 100MHz

    input                       sb_node_debug_en    ,
    input                       sb_debug_tx_vld     ,
    input   [31:0]              sb_debug_tx_data    ,
    output  logic               sb_debug_tx_rdy     ,
    input                       i_lp_cfg_vld        , // upper layer l2p
    input   [31:0]              i_lp_cfg            ,
    //input                       i_lp_cfg_crd        ,
    input                       i_pl_cfg_crd        ,
    input                       mailbox_req_vld     , // keep high until mailbox_req_data goes into fifo 
    input   [127:0]             mailbox_req_data    , // mailbox request to adapter for remote access
    output  logic               mailbox_req_rdy     , // indicates mailbox_req_vld should de-assert
    input                       msg_gen_vld         , // local message gen to remote
    input   [127:0]             msg_gen_data        , 
    output  logic               msg_gen_rdy         ,   
    input                       rt_local_req_vld    , // remote to local req of physical from RX NODE
    input   [127:0]             rt_local_req_data   , 
    output  logic               rt_local_req_rdy    , 
    output  logic [4:0]         remote_tag          , // original tag for rt_local_req
    output  logic [4:0]         remote_tag_remap    , // remap tag for rt_local_req
    input                       rt_remote_cmpl_vld  , // 1 cycle pulse
    input   [127:0]             rt_remote_cmpl_data , // from sb_rx_node, the only src for adapter
    output  logic               rt_remote_cmpl_rdy  ,

    input                       remote_cr_vld       ,
    input   [2:0]               remote_cr           ,
    input                       cmpl_tag_rd         , // read completion tag buffer
    input   [4:0]               cmpl_tag            ,
    output  logic [9:0]         cmpl_tag_info       , // 1 clock latency

    output  logic               lmem_cm             , // config or memory access
    output  logic               lmem_ce             , // local req consume
    output  logic [23:0]        lmem_addr           ,
    output  logic               lmem_we             ,
    output  logic [7:0]         lmem_be             ,
    output  logic [63:0]        lmem_wdata          ,
    input   [63:0]              lmem_rdata          , // read latency, 1 clock
    output  logic               o_lp_cfg_vld        , // lower layer l2p
    output  [31:0]              o_lp_cfg            ,
    //output  logic               o_lp_cfg_crd        ,
    output  logic               o_pl_cfg_crd        ,
    output  logic               cp_err              ,
    output  logic               dp_err              ,
    input                       tr_local_cmpl_rdy   ,
    output  logic               tr_local_cmpl_vld   , // responce to local req
    output  logic [127:0]       tr_local_cmpl_data  ,
    output  logic [4:0]         tx_node_credit      ,
    output  logic [4:0]         tx_node_r_credit      // remote credit 

);

