`timescale 1ns/1ps  

module  M2_clci_ace_wrapper #(
    parameter   ACE_HAS_MASTER = 1, // connect to slave if.  1: ture; 0: no
    parameter   ACE_HAS_SLAVE = 1,  // connect to master if. 1: true; 0: no
    parameter   DW = 128 ,
    parameter   TX_FIFO_ADDR_WIDTH = 5 ,
    parameter   RX_FIFO_ADDR_WIDTH = 7
)
(
    input                   rst_n                   ,
    input                   clk                     ,

    input                   scan_mode               ,
    input                   ace_legacy_mode         ,

    output                  slv_awready             ,
    input                   slv_awvalid             ,
    input   [15:0]          slv_awid                ,
    input   [43:0]          slv_awaddr              ,
    input   [7:0]           slv_awlen               ,
    input   [2:0]           slv_awsize              ,
    input   [1:0]           slv_awburst             ,
    input   [3:0]           slv_awregion            ,
    input                   slv_awlock              ,
    input   [3:0]           slv_awcache             ,
    input   [2:0]           slv_awprot              ,
    input   [3:0]           slv_awqos               ,
    input   [2:0]           slv_awsnoop             ,
    input   [1:0]           slv_awdomain            ,
    input   [1:0]           slv_awbar               ,
    input                   slv_awunique            ,

    output                  slv_arready             ,
    input                   slv_arvalid             ,
    input   [15:0]          slv_arid                ,
    input   [43:0]          slv_araddr              ,
    input   [7:0]           slv_arlen               ,
    input   [2:0]           slv_arsize              ,
    input   [1:0]           slv_arburst             ,
    input   [3:0]           slv_arregion            ,
    input                   slv_arlock              ,
    input   [3:0]           slv_arcache             ,
    input   [2:0]           slv_arprot              ,
    input   [3:0]           slv_arqos               ,
    input   [3:0]           slv_arsnoop             ,
    input   [1:0]           slv_ardomain            ,
    input   [1:0]           slv_arbar               ,

    output                  slv_crready             ,
    input                   slv_crvalid             ,
    input   [4:0]           slv_crresp              ,

    output                  slv_wready              ,
    input                   slv_wvalid              ,
    input   [DW-1:0]        slv_wdata               ,
    input   [DW/8-1:0]      slv_wstrb               ,
    input                   slv_wlast               ,

    output                  slv_cdready             ,
    input                   slv_cdvalid             ,
    input   [DW-1:0]        slv_cddata              ,
    input                   slv_cdlast              ,

    input                   slv_bready              ,
    output                  slv_bvalid              ,
    output  [15:0]          slv_bid                 ,
    output  [1:0]           slv_bresp               ,

    input                   slv_acready             ,
    output                  slv_acvalid             ,
    output  [14:0]          slv_acvid               ,
    output  [43:0]          slv_acaddr              ,
    output  [3:0]           slv_acsnoop             ,
    output  [2:0]           slv_acprot              ,

    input                   slv_rready              ,
    output                  slv_rvalid              ,
    output  [15:0]          slv_rid                 ,
    output  [DW-1:0]        slv_rdata               ,
    output  [3:0]           slv_rresp               ,
    output                  slv_rlast               ,

    input                   slv_wack                ,
    input                   slv_rack                ,

    input                   otherside_rx_rd_afull   ,
    input                   otherside_rx_wd_afull   ,
    input                   otherside_rx_cd_afull   ,
    input                   mac_tx_pause            ,
    input   [2:0]           arb_wd_rd_cd            ,

    output                  mac_tx_valid            ,
