//==============================================================================
//  Copyright 2023@M2SEMI Technologies, Inc.
//  Created By  : xcliu
//  File Name   : clci_ace_tx.v
//  Created On  : 2023-04-25 15:34
//
//  Revision    :
//  
//  2023-07-12  : add ace_legacy_mode to support backward compatibility with 
//                CL2104 ace 128-bit interface
//                AC vid bitwidth truncate to 15-bit
//
//  2023-10-18  : simplify wd_rd_cd arbiter, support only 4 mode
//  2023-12-19  : wack and rack now locate to all type of flits to improve
//                write efficiency
//  2023-12-22  : modify ace128 8 channel encoding
//                flit format 0: slv_AW + slv_W + slv_wack
//                flit format 1: slv_AR + slv_CR + slv_rack + slv_CD
//                flit format 2: mst_AC + mst_B + mst_R
//
///==============================================================================

`timescale 1ns/1ps  

module M2_clci_ace_tx #(
    parameter   ACE_HAS_MASTER = 1,
    parameter   ACE_HAS_SLAVE = 1,
    parameter   DW = 256 ,
    parameter   FIFO_ADDR_WIDTH = 5
)(
    input               rst_n                   ,
    input               clk                     ,

    input               scan_mode               ,
    input               ace_legacy_mode         , 

    output              slv_awready             ,
    input               slv_awvalid             ,
    input   [15:0]      slv_awid                ,
    input   [43:0]      slv_awaddr              ,
    input   [7:0]       slv_awlen               ,
    input   [2:0]       slv_awsize              ,
    input   [1:0]       slv_awburst             ,
    input   [3:0]       slv_awregion            ,
    input               slv_awlock              ,
    input   [3:0]       slv_awcache             ,
    input   [2:0]       slv_awprot              ,
    input   [3:0]       slv_awqos               ,
    input   [2:0]       slv_awsnoop             ,
    input   [1:0]       slv_awdomain            ,
    input   [1:0]       slv_awbar               ,
    input               slv_awunique            ,

    output              slv_arready             ,
    input               slv_arvalid             ,
    input   [15:0]      slv_arid                ,
    input   [43:0]      slv_araddr              ,
    input   [7:0]       slv_arlen               ,
    input   [2:0]       slv_arsize              ,
    input   [1:0]       slv_arburst             ,
    input   [3:0]       slv_arregion            ,
    input               slv_arlock              ,
    input   [3:0]       slv_arcache             ,
    input   [2:0]       slv_arprot              ,
    input   [3:0]       slv_arqos               ,
    input   [3:0]       slv_arsnoop             ,
    input   [1:0]       slv_ardomain            ,
    input   [1:0]       slv_arbar               ,

    output              slv_crready             ,
    input               slv_crvalid             ,
    input   [4:0]       slv_crresp              ,

    output              slv_wready              ,
    input               slv_wvalid              ,
    input   [DW-1:0]    slv_wdata               ,
    input   [DW/8-1:0]  slv_wstrb               ,
    input               slv_wlast               ,

    output              slv_cdready             ,
    input               slv_cdvalid             ,
    input   [DW-1:0]    slv_cddata              ,
    input               slv_cdlast              ,

    output              mst_bready              ,
    input               mst_bvalid              ,
    input   [15:0]      mst_bid                 ,
    input   [1:0]       mst_bresp               ,

    output              mst_acready             ,
    input               mst_acvalid             ,
    input   [14:0]      mst_acvid               ,
    input   [43:0]      mst_acaddr              ,
    input   [3:0]       mst_acsnoop             ,
    input   [2:0]       mst_acprot              ,

    output              mst_rready              ,
    input               mst_rvalid              ,
    input   [15:0]      mst_rid                 ,
    input   [DW-1:0]    mst_rdata               ,
    input   [3:0]       mst_rresp               ,
    input               mst_rlast               ,

    input               slv_wack                ,
    input               slv_rack                ,

    input               aw_ost_acpt_ready       ,
    input               ar_ost_acpt_ready       ,
    input               ac_ost_acpt_ready       ,
    input               otherside_rx_rd_afull   ,
    input               otherside_rx_wd_afull   ,
    input               otherside_rx_cd_afull   ,
    input               mac_tx_pause            ,
    input   [2:0]       arb_wd_rd_cd            ,

    output              mac_tx_valid            ,
    output  [291:0]     mac_tx_data_h           ,
    output  [291:0]     mac_tx_data_l           ,
    output              tx_fifo_empty_flag      ,
    output  [19:0]      dbg_bus


);


