`timescale 1ns/1ps    

module M2_clci_swerv_subsys #(
    parameter   MCU_LEVEL       =   "CLCI_MCU"  ,
    parameter   MCU_RAM_VOLUME  =   "32KB"      , // only support 32KB
    parameter   I2C_DEV_ID      =   8'hAC       ,
    parameter   I2C_MTBF_STAGE  =   3           ,
    parameter   I2C_DEB_STAGE   =   5           ,
    parameter   I2C_AW          =   32          ,
    parameter   REBOOT_SRC      =   32'h0       ,
    parameter   VENDOR_ID       =   16'h00AB    ,
    parameter   REVISION_ID     =   16'h2511    ,
    parameter   DEVICE_ID       =   32'h2       ,
    parameter   SYNC_LEVEL      =   2
)(
    input                   mcu_clk                  , //25~200MHz
    input                   mcu_rstn                 ,
    input                   ref_clk                  , //25MHz
    input                   ref_rstn                 ,
    // io & ctrl
    input                   wdt_sim_speed            ,
    input   [3:0]           strapping_mode           ,
    input   [1:0]           boot_sel                 ,
    input   [7:0]           chiplet_id               ,
    input   [7:0]           i2c_change_id            ,
    input   [31:0]          mcu_id                   ,
    input   [31:0]          mcu_jtag_id              ,
    input                   i2c_scl_in               ,
    input                   i2c_sda_in               ,
    output                  i2c_sda_oe_n             ,
    input                   uart_rx0                 ,
    output                  uart_tx0                 ,
    input                   uart_rx1                 ,
    output                  uart_tx1                 ,
    input                   tck                      ,
    input                   tms                      ,
    input                   tdi                      ,
    input                   trst_n                   ,
    output                  tdo                      ,
    output                  tdo_en                   ,
    input                   normal_mode              ,
    input                   scan_mode                ,
    input                   scan_en                  ,
    input                   scan_clk                 ,
    input                   mbist_mode               ,
    input                   clci_mission_irq         ,
    input                   clci_error_irq           ,
    input   [95:0]          sram_sys_cfg             ,
    output                  db2soc_irq               ,
    //output                  mcu_sbit_err_irq         ,
    //output                  mcu_dbit_err_irq         ,
    //output                  ahb_timeout_irq_sync     ,
    output                  wdt_irq_sync             ,


    output  [3:0]           fdi_pl_state_sts_pclk    ,
    output  [3:0]           rdi_pl_state_sts_pclk    ,
    output  [7:0]           phy_ltsm_state_pclk      ,
    output  [3:0]           sb_init_gpio_tx          ,
    input   [3:0]           sb_init_gpio_rx          ,
    
    input                   fdi_clk                  ,
    input                   fdi_rst_n                ,

    // ucie sideband0
    input                   sb0_link_rx_vld          ,
    input   [31:0]          sb0_link_rx_data         ,
    input                   sb0_rdi_rx_vld           ,
    input   [31:0]          sb0_rdi_rx_data          ,
    input                   sb0_fdi_rx_vld           ,
    input   [31:0]          sb0_fdi_rx_data          ,
//    input                   sb0_app_rx_vld           ,
//    input   [31:0]          sb0_app_rx_data          ,
    //input                   sb0_link_rx_rdy          ,
    input                   sb0_link_tx_rdy          ,
    input                   sb0_rdi_tx_rdy           ,
    input                   sb0_fdi_tx_rdy           ,
    output  [31:0]          sb0_cmpl_timeout_cnt     ,
    input                   sb0_adapter_cmpl_timeout ,
    input                   sb0_tx_credit_runout     ,
    input                   sb0_adapter_tx_cp_err    ,
    input                   sb0_adapter_tx_dp_err    ,
    input   [4:0]           sb0_adapter_tx_credit    ,
    input                   sb0_adapter_rx_cp_err    ,
    input                   sb0_adapter_rx_dp_err    ,
    input   [4:0]           sb0_adapter_rx_credit    ,
    input                   sb0_physical_tx_cp_err   ,
    input                   sb0_physical_tx_dp_err   ,
    input   [4:0]           sb0_physical_tx_credit   ,
    input                   sb0_physical_rx_cp_err   ,
    input                   sb0_physical_rx_dp_err   ,
    input   [4:0]           sb0_physical_rx_credit   ,
    input   [3:0]           sb0_tx_p2s_state_debug   ,
    input   [3:0]           sb0_init_state_debug     ,
    input                   sb0_init_done            ,
    input   [3:0]           sb0_init_done_debug      ,
    input                   sb0_train_error          ,
    output                  sb0_link_tx_vld          ,
    output  [31:0]          sb0_link_tx_data         ,
    output                  sb0_link_rx_irdy         ,
    output                  sb0_rdi_tx_vld           ,
    output  [31:0]          sb0_rdi_tx_data          ,
    output                  sb0_rdi_rx_irdy          ,
    output                  sb0_fdi_tx_vld           ,
    output  [31:0]          sb0_fdi_tx_data          ,
    output                  sb0_fdi_rx_irdy          ,
//    output                  sb0_app_tx_vld           ,
//    output  [31:0]          sb0_app_tx_data          ,
//    output                  sb0_app_rx_irdy          ,
    output                  sb0_pmo_mode             ,
    output  [3:0]           sb0_tx_init_rd_sel       ,
    output                  sb0_ctrl_rstn            ,
    output                  sb0_force_init_done      ,
    output                  sb0_init_8ms_en          ,
    output                  sb0_init_start           ,
    output                  sb0_link_if_en           ,
    output                  sb0_fdi_if_en            ,
    output                  sb0_rdi_if_en            ,
    output  [15:0]          sb0_gpio_trig_gap        ,
    output                  sb0_gpio_trans_en        ,
    output                  sb0_auto_link_disable    ,
    output                  sb0_io_mode              , 
    output                  sb0_rxdata_loop_en       , 
    output                  sb0_rxck_loop_en         , 
    output  [3:0]           sb0_rxdata_ctrl_rt       , 
    output  [3:0]           sb0_rxck_ctrl_rt         , 
    output                  sb0_rxdata_enable        , 
    output                  sb0_rxck_enable          , 
    output                  sb0_txdata_enable        , 
    output                  sb0_txck_enable          , 
    output  [3:0]           sb0_rxdata_delaycode     , 
    output  [3:0]           sb0_rxck_delaycode       , 
    output                  sb0_loopback_mode        , 
    output                  sb0_rx_phase_sel         , 
    output  [1:0]           sb0_tx_sclk_mux_sel      , 
    output  [8:0]           sb0_rxdata_test          , 
    output  [8:0]           sb0_rxck_test            , 
    output  [6:0]           sb0_txdata_test          , 
    output  [6:0]           sb0_txck_test            , 
    //output                  sb0_macro_rstn           ,
    //output  [1:0]           sb0_tx_sclk_mux_sel      ,
    //output                  sb0_tx_phase_sel         ,
    //output                  sb0_rx_phase_sel         ,
    //output                  sb0_loopback_mode        ,
    //output  [2:0]           sb0_rxdata_rterm_pd_trim ,
    //output  [2:0]           sb0_rxdata_rterm_pu_trim ,
    //output  [2:0]           sb0_rxck_rterm_pd_trim   ,
    //output  [2:0]           sb0_rxck_rterm_pu_trim   ,
    //output  [2:0]           sb0_rxdata_sense_pd_trim ,
    //output  [2:0]           sb0_rxdata_sense_pu_trim ,
    //output  [2:0]           sb0_rxck_sense_pd_trim   ,
    //output  [2:0]           sb0_rxck_sense_pu_trim   ,
    //output  [1:0]           sb0_ltcy_trim            ,
    //output                  sb0_txck_enable          ,
    //output                  sb0_txdata_enable        ,
    //output                  sb0_rxck_enable          ,
    //output                  sb0_rxdata_enable        ,
    //output  [1:0]           sb0_rxck_schm_en         ,
    //output  [1:0]           sb0_rxdata_schm_en       ,
    //output                  sb0_io_mode              ,

    input                   soc_clk                  , //connect to mcu_clk 
    input                   soc_rstn                 , //connect to mcu_clk
    // ahb ifs
    input                   soc_i_psel               ,
    input                   soc_i_penable            ,
    input                   soc_i_pwrite             ,
    input   [31:0]          soc_i_paddr              ,
    input   [31:0]          soc_i_pwdata             ,
    output                  soc_i_pready             ,
    output  [31:0]          soc_i_prdata             ,
    output                  soc_i_pslverr            ,

    output                  rt_m_awready             ,
    input                   rt_m_awvalid             ,
    input   [3:0]           rt_m_awid                ,
    input   [31:0]          rt_m_awaddr              ,
    input   [7:0]           rt_m_awlen               ,
    input   [2:0]           rt_m_awsize              ,
    input   [1:0]           rt_m_awburst             ,
    input   [3:0]           rt_m_awregion            ,
    input                   rt_m_awlock              ,
    input   [3:0]           rt_m_awcache             ,
    input   [2:0]           rt_m_awprot              ,
    input   [3:0]           rt_m_awqos               ,
    output                  rt_m_wready              ,
    input                   rt_m_wvalid              ,
    input   [63:0]          rt_m_wdata               ,
    input   [7:0]           rt_m_wstrb               ,
    input                   rt_m_wlast               ,
    input                   rt_m_bready              ,
    output                  rt_m_bvalid              ,
    output  [3:0]           rt_m_bid                 ,
    output  [1:0]           rt_m_bresp               ,
    output                  rt_m_arready             ,
    input                   rt_m_arvalid             ,
    input   [3:0]           rt_m_arid                ,
    input   [31:0]          rt_m_araddr              ,
    input   [7:0]           rt_m_arlen               ,
    input   [2:0]           rt_m_arsize              ,
    input   [1:0]           rt_m_arburst             ,
    input   [3:0]           rt_m_arregion            ,
    input                   rt_m_arlock              ,
    input   [3:0]           rt_m_arcache             ,
    input   [2:0]           rt_m_arprot              ,
    input   [3:0]           rt_m_arqos               ,
    input                   rt_m_rready              ,
    output                  rt_m_rvalid              ,
    output  [3:0]           rt_m_rid                 ,
    output  [63:0]          rt_m_rdata               ,
    output  [1:0]           rt_m_rresp               ,
    output                  rt_m_rlast               ,
    
    // sideband master apb
    input                   sb_m_pready              ,
    input   [31:0]          sb_m_prdata              ,
    output                  sb_m_psel                ,
    output                  sb_m_penable             ,
    output                  sb_m_pwrite              ,
    output  [23:0]          sb_m_paddr               ,
    output  [31:0]          sb_m_pwdata              ,

    // apb to biu
    input   [31:0]          prdata_biu               ,
    output                  psel_biu                 ,
    output  [31:0]          paddr_biu                ,
    output                  penable_biu              ,
    output                  pwrite_biu               ,
    output  [31:0]          pwdata_biu               ,
    output                  biu_rst_n


);

