`timescale 1ns/1ps  

module  M2_axi4_to_sram #(
    parameter   ID_W = 4
)(
    input                   aclk,
    input                   aresetn,
    input                   arvalid,
    output reg              arready,
    input [31:0]            araddr,
    input [ID_W-1:0]        arid,
    input [7:0]             arlen,
    input [1:0]             arburst,
    input [2:0]             arsize,
    output reg              rvalid,
    input                   rready,
    output [63:0]           rdata,
    output reg [1:0]        rresp,
    output reg [ID_W-1:0]   rid,
    output                  rlast,
    input                   awvalid,
    output                  awready,
    input [31:0]            awaddr,
    input [ID_W-1:0]        awid,
    input [7:0]             awlen,
    input [1:0]             awburst,
    input [2:0]             awsize,
    input [63:0]            wdata,
    input [7:0]             wstrb,
    input                   wvalid,
    output                  wready,
    output reg              bvalid,
    input                   bready,
    output reg [1:0]        bresp,
    output reg [ID_W-1:0]   bid,
   
    output                  ram_ce,
    output                  ram_we,
    output  [31:0]          ram_addr,
    output  [63:0]          ram_be,
    output  [63:0]          ram_wdata,
    input   [63:0]          ram_rdata

);

