`timescale 1ns/1ps  

module M2_sram_parity_4096x64
#(
    parameter SYNC_LEVEL = 2      // sync cell level
) (
    input                               clk                 ,
    input                               rst_n               ,
    input                               ce                  ,
    input                               we                  ,
    input   [11:0]                      addr                ,
    input   [63:0]                      be                  ,
    input   [63:0]                      wdata               ,
    output                              rdata_vld           ,
    output  [63:0]                      rdata               ,
    output                              busy                ,
    input   [95:0]                      sram_sys_cfg        ,
 
    input                               cfg_clk             ,
    input                               cfg_rst_n           ,    
    input                               test_mode           ,

    // interrupt controls
    input                               pipe_reg_en         ,
    input                               parity_enable       ,
    input                               parity_err_inj      ,

    // int controls
    input                               parity_err_int_clr  ,
    input                               parity_err_int_mask ,
    output wire                         parity_err_int_rpt  ,

    // parity error reporting
    output wire [12             -1:0]   parity_err_faddr    ,
    output wire [12             -1:0]   parity_err_laddr    ,
    input                               parity_err_cnt_clr  ,
    output wire [32             -1:0]   parity_err_cnt      
 
);
