`ifndef __M2_SWERV_I2C2AXI_AXI__
`define __M2_SWERV_I2C2AXI_AXI__

`resetall
`timescale 1ns/100ps

module M2_swerv_i2c2axi_axi #(
  parameter DEV_ID      = 8'hAC,
  parameter MTBF_STAGE  = 3,
  parameter DEB_STAGE   = 5,
  parameter AXI_AW      = 40,
  parameter AXI_IDW     = 4,
  parameter AXI_DW      = 128,
  parameter AXI_STRBW   = AXI_DW/8
)(
  input       [AXI_AW-1:0]      i2c_addr,
  input                         i2c_w,
  input                         i2c_r,
  input       [1:0]             i2c_len,
  input       [3:0]             i2c_strb,
  input       [31:0]            i2c_wdata_p,
  input       [31:0]            i2c_wdata,
  output reg  [31:0]            i2c_rdata,
  output                        i2c_finish,
  output                        fabric_done,

  // Write Address Channel
  output reg  [AXI_AW-1:0]      awaddr,
  output      [AXI_IDW-1:0]     awid,
  output      [4-1:0]           awlen,
  output reg  [3-1:0]           awsize,
  output      [2-1:0]           awburst,
  output      [1-1:0]           awlock,
  output      [4-1:0]           awcache,
  output      [3-1:0]           awprot,
  output reg                    awvalid,
  input                         awready,

  // Write Data Channel
  output      [AXI_DW-1:0]      wdata,
  output      [AXI_STRBW-1:0]   wstrb,
  output                        wlast,
  output reg                    wvalid,
  input                         wready,

  // Write Response Channel
  input       [AXI_IDW-1:0]     bid,
  input       [2-1:0]           bresp,
  input                         bvalid,
  output                        bready,

  // Read Address Channel
  output reg  [AXI_AW-1:0]      araddr,
  output      [AXI_IDW-1:0]     arid,
  output      [4-1:0]           arlen,
  output reg  [3-1:0]           arsize,
  output      [2-1:0]           arburst,
  output      [1-1:0]           arlock,
  output      [4-1:0]           arcache,
  output      [3-1:0]           arprot,
  output reg                    arvalid,
  input                         arready,

  // Read Data Channel
  input       [AXI_IDW-1:0]     rid,
  input       [AXI_DW-1:0]      rdata,
  input                         rlast,
  input       [2-1:0]           rresp,
  input                         rvalid,
  output                        rready,

  input                         clk,
  input                         rstn
);

// ============================================

