`ifndef __M2_SWERV_I2C2AXI_ITXC__
`define __M2_SWERV_I2C2AXI_ITXC__

`resetall
`timescale 1ns/100ps

module M2_swerv_i2c2axi_itxc #(
  parameter DEV_ID      = 8'hAC,
  parameter MTBF_STAGE  = 3,
  parameter DEB_STAGE   = 5,
  parameter AXI_AW      = 40,
  parameter AXI_IDW     = 4,
  parameter AXI_DW      = 128,
  parameter AXI_STRBW   = AXI_DW/8
) (
  input                         scl_in,
  input                         sda_in,

  output                        sda_o_valid,
  output                        sda_oen,

  output      [AXI_AW-1:0]      i2c_addr,
  output                        i2c_w,
  output                        i2c_r,
  output      [1:0]             i2c_len,
  output      [3:0]             i2c_strb,
  output      [31:0]            i2c_wdata_p,
  output      [31:0]            i2c_wdata,
  input       [31:0]            i2c_rdata,
  input                         i2c_finish,

  input                         fabric_done,

  input                         new_id_valid,
  input       [6:0]             new_id,

  input                         clk,
  input                         rstn
);
