`ifndef __M2_SWERV_I2C2AXI_TOP__
`define __M2_SWERV_I2C2AXI_TOP__

`resetall
`timescale 1ns/100ps

module M2_swerv_i2c2axi_top #(
  parameter DEV_ID      = 8'hAC,
  parameter MTBF_STAGE  = 3,
  parameter DEB_STAGE   = 9,
  parameter AXI_AW      = 40,
  parameter AXI_IDW     = 4,
  parameter AXI_DW      = 128,
  parameter AXI_STRBW   = AXI_DW/8,
  parameter SYNC_LEVEL  = 2
) (
  input                         scl_in,             //io
  input                         sda_in,        //io
  output                        sda_o_valid,   //io
  output                        sda_oen,            //io

  // Write Address Channel
  output      [AXI_AW-1:0]      awaddr,
  output      [AXI_IDW-1:0]     awid,
  output      [4-1:0]           awlen,
  output      [3-1:0]           awsize,
  output      [2-1:0]           awburst,
  output      [1-1:0]           awlock,
  output      [4-1:0]           awcache,
  output      [3-1:0]           awprot,
  output                        awvalid,
  input                         awready,

  // Write Data Channel
  output      [AXI_DW-1:0]      wdata,
  output      [AXI_STRBW-1:0]   wstrb,
  output                        wlast,
  output                        wvalid,
  input                         wready,

  // Write Response Channel
  input       [AXI_IDW-1:0]     bid,
  input       [2-1:0]           bresp,
  input                         bvalid,
  output                        bready,

  // Read Address Channel
  output      [AXI_AW-1:0]      araddr,
  output      [AXI_IDW-1:0]     arid,
  output      [4-1:0]           arlen,
  output      [3-1:0]           arsize,
  output      [2-1:0]           arburst,
  output      [1-1:0]           arlock,
  output      [4-1:0]           arcache,
  output      [3-1:0]           arprot,
  output                        arvalid,
  input                         arready,

  // Read Data Channel
  input       [AXI_IDW-1:0]     rid,
  input       [AXI_DW-1:0]      rdata,
  input                         rlast,
  input       [2-1:0]           rresp,
  input                         rvalid,
  output                        rready,

  // cfg
  input       [7:0]             change_id,

  input                         ptest_scan_mode,

  input                         clk,
  input                         rstn
);


