// Function: Instruction aligner
//********************************************************************************
module M2_el2_ifu_aln_ctl
import el2_pkg_M2::*;

`protected128
PJWY8(/\QH+25K4H0[^YQ8^++C;-?!I8=DK&WGM\!B?&\%W)4Y513C#9MYZ^BN,_Y
