module M2_el2_dec_tlu_ctl
import el2_pkg_M2::*;

`protected128
P3S<<5$F \1QF3]T%?_;/7L)N%B)9&/P?K[V^F93)N5(0+.NZJV@>45BJ<M;?WZ&>
