module M2_clcis_apb_uart_bcm06 (
    clk,
    rst_n,
    init_n,
    push_req_n,
    pop_req_n,
    diag_n,
    ae_level,
    af_thresh,
    we_n,
    empty,
    almost_empty,
    half_full,
    almost_full,
    full,
    error,
    wr_addr,
    rd_addr,
    wrd_count,
    nxt_empty_n,
    nxt_full,
    nxt_error
    );

`protected128
PMA9K4[>H5;*,B@!.]2Y-NV ;^OUQA88]*8?/U9H!_D6%@.1PT7_^@_[.DO4TN%RE
P7M8?7+"QG2<U)L!TQ]N%Q?.H$JEID1;DDK3+(QO8;5%<BEG.,S>V;K:SP+:<EB6!
