//leda NTL_CON10 off
//LMD: Output tied to supply
//LJ : This is an on-chip debug signal used for debugging.Some of the bits are not used or
//     reserved for any future needs.
//leda NTL_CON10A off
//LMD: Output tied to supply in top level module
//LJ : This is an on-chip debug signal used for debugging.Some of the bits are not used or
//     reserved for any future needs.
module M2_clcis_apb_uart
//leda NTL_CON10A on
//leda NTL_CON10 on
  (
   // Inputs
   pclk,
   presetn,
   penable,
   pwrite,
   pwdata,
   paddr,
   psel,
   scan_mode,
   cts_n,
   dsr_n,
   dcd_n,
   ri_n,
   sin,
   // Outputs
   prdata,
   dtr_n,
   rts_n,
   out2_n,
   out1_n,
   dma_tx_req,
   dma_rx_req,
   txrdy_n,
   rxrdy_n,
   sout,
   intr
   );
   input                              pclk;                   // APB Clock
   input                              presetn;                // APB active low
                                                              // async reset
   input                              penable;                // strobe signal
   input                              pwrite;                 // write enable
   input  [`APB_DATA_WIDTH-1:0]       pwdata;                 // write data bus
//leda NTL_CON37 off
//LMD: Signal/Net must read from the input port in module
//LJ : paddr[1:0] is used to select byte enable signal.
//     IN APB_DATA_WIDTH=32 configuration, all four bytes of a 32 bit
//     register is enabled. Hence the LSB two bits are not used in this configuration.


   input  [`UART_ADDR_SLICE_LHS-1:0]  paddr;                  // address bus
//leda NTL_CON37 on

   input                              psel;                   // APB peripheral
                                                              // select
                                                              // low async reset
   input                              scan_mode;              // scan mode signal
                                                              // RAM
                                                              // RAM
   input                              cts_n;                  // clear to send,
                                                              // active low
   input                              dsr_n;                  // data set ready,
                                                              // active low
   input                              dcd_n;                  // data carrier detect,
                                                              // active low
   input                              ri_n;                   // ring indicator,
                                                              // active low
                                                              // active high
                                                              // active low
                                                              // active high
                                                              // active low
   input                              sin;                    // serial in

   output [`APB_DATA_WIDTH-1:0]       prdata;                 // read data bus

                                                              // RAM

                                                              // for TX FIFO RAM

                                                              // for TX FIFO RAM

                                                              // TX FIFO RAM,
                                                              // active low

                                                              // TX FIFO RAM,
                                                              // active low

                                                              // chip enable for
                                                              // external ram,
                                                              // active low

                                                              // RAM

                                                              // for RX FIFO RAM

                                                              // for RX FIFO RAM

                                                              // RX FIFO RAM,
                                                              // active low

                                                              // RX FIFO RAM,
                                                              // active low

                                                              // chip enable for
                                                              // external ram,
                                                              // active low

   output                             dtr_n;                  // data terminal ready,
                                                              // active low

   output                             rts_n;                  // request to send,
                                                              // active low

   output                             out2_n;                 // programmable output2,
                                                              // active low

   output                             out1_n;                 // programmable output1,
                                                              // active low

   output                             dma_tx_req;             // TX buffer ready,
                                                              // active high

                                                              // active low

                                                              // active high

                                                              // active low

   output                             dma_rx_req;             // RX buffer ready,
                                                              // active high

                                                              // active low

                                                              // active high

                                                              // active low

   output                             txrdy_n;                // legacy DMA TX
                                                              // buffer ready,
                                                              // active low

   output                             rxrdy_n;                // legacy DMA rx
                                                              // buffer ready,
                                                              // active low

   output                             sout;                   // serial out

                                                              // active low



                                                              // active low


   output                             intr;                   // interrupt




   
