// Name:         APB_DATA_WIDTH
// Default:      32
// Values:       8 16 32
// 
// APB Data bus width 
// Width of APB Data Bus to which this peripheral is attached
`define APB_DATA_WIDTH 32

//Maximum allowed APB Data bus width

`define MAX_APB_DATA_WIDTH 32


// Name:         WDT_CNT_WIDTH
// Default:      32
// Values:       16, ..., 32
// 
// Width of WDT Counter, can be 16 to 32 bits
`define WDT_CNT_WIDTH 32


// Name:         WDT_INT_POL
// Default:      true
// Values:       false (0), true (1)
// Enabled:      !(WDT_HC_RMOD==1 && WDT_DFLT_RMOD==0)
// 
// Polarity of the generated interrupt
`define WDT_INT_POL 1


// Name:         WDT_RST_POL
// Default:      true
// Values:       false (0), true (1)
// 
// Polarity of the generated reset
`define WDT_RST_POL 0


// Name:         WDT_HC_TOP
// Default:      false
// Values:       false (0x0), true (0x1)
// 
// Selects the timeout period(s) to be hard code
`define WDT_HC_TOP 1'h0


// Name:         WDT_DUAL_TOP
// Default:      false
// Values:       false (0), true (1)
// 
// Optional additional timeout period select which configures 
// the macrocell to have a second timeout period that is used 
// for initialization prior to the first kick
`define WDT_DUAL_TOP 0


// Name:         WDT_DFLT_TOP
// Default:      0
// Values:       0, ..., 15
// 
// Select the timeout period that is available directly after reset. 
// That is the range (0-15) that corresponds to the desiered timeout period. 
// If the timeout period is hard coded then this is the only possible 
// timeout period
`define WDT_DFLT_TOP 8


// Name:         WDT_DFLT_TOP_INIT
// Default:      0
// Values:       0, ..., 15
// Enabled:      WDT_DUAL_TOP==1
// 
// Select the initial timeout period that is available directly after reset. 
// That is the range (0-15) that corresponds to the desiered timeout period. 
// If the timeout period is hard coded then this is the only possible 
// initial timeout period. Only relevant when the WDT is configured to 
// have dual timeout periods
`define WDT_DFLT_TOP_INIT 0


// Name:         WDT_USE_FIX_TOP
// Default:      true
// Values:       false (0x0), true (0x1)
// 
// Select the timeout periods that is used, either a pre-defined (fixed) timeout 
// period range which increments by the power of 2 from 2 to the power of (16) 
// to 2 to the power of (the WDT counter width minus 1) or user defined timeout 
// period range, values can be anything from 2 to the power of (8) minus 1, 
// to 2 to the power of (the WDT counter width) minus 1
`define WDT_USE_FIX_TOP 1'h1


// Name:         WDT_USER_TOP_0
// Default:      0xffff
// Values:       0xff, ..., [calc_user_top_limit WDT_CNT_WIDTH]
// Enabled:      WDT_USE_FIX_TOP==0 && !(WDT_HC_TOP==1 && WDT_DFLT_TOP!=0)
// 
// User defined main timeout period for range 0 described by the WDT_TORR 
// register bits[3:0] (TOP). Only relevant when the WDT is configured 
// not to use the pre-defined (fixed) timeout periods and if the timeout 
// period is hard coded that this is the default. The value chosen must be 
// less than or equal to: 2 to the power of (the WDT counter width) 
// minus 1
`define WDT_USER_TOP_0 32'hffff


// Name:         WDT_USER_TOP_1
// Default:      0x1ffff
// Values:       0xff, ..., [calc_user_top_limit WDT_CNT_WIDTH]
