module M2_clcis_apb_wdt_biu
(
 // APB bus bus interface
 pclk,
 presetn,
 psel,
 penable,
 pwrite, 
 paddr,
 pwdata,
 prdata,

 // regfile interface
 wr_en,
 rd_en,
 byte_en,
 reg_addr,
 ipwdata,
 iprdata
 );

   `protected128
PEW??J$3$&PRG:[#EU5_2C+6RT*R^8T1P-!J%H!2FIQ 2OWP(7;JBE='MS3L$$H'?
P:&$!('^:96;V^$>XR#/2A&EO>GEV:@A)S&\8W&S*49R!34.6WBN]N0W/5&F]45ZV
PTB3J7]XCX@Y3\5E:":0XK05\Y@G<+8O([H[X5B%;4F(1U]?WY2PD#&\B'[BZ\L4Z
PS<HL!7K*S-V^=2PR'+;'>OZ(..TLZ5.XT/HL&P+M]C%' NG+*WF7J R8#\)<0QO+
PW#[+QZ:;2H:&_5C#.0;*SG0"""CQP%UCPPN3<GCXFEG,QR^XE8]C50VU(I*#S\2^
`endprotected128
input                            pclk;      // APB clock
   input                            presetn;   // APB reset
   input                            psel;      // APB slave select
//leda NTL_CON37 off
//LMD: Signal/Net must read from the input port in module
//LJ : LSB Bits of paddr are used to select byte enable signal.
//     IN APB_DATA_WIDTH=32 configuration, all four bytes of a 32 bit
//     register is enabled. Hence the LSB two bits are not used in this configuration.
//leda NTL_CON13C off
//LMD: non driving port
//LJ : LSB bits of paddr is used to select byte enable signal.
//     IN APB_DATA_WIDTH=32 configuration, all four bytes of a 32 bit
//     register is enabled. Hence the LSB two bits are not used in this configuration.
   input       [ADDR_SLICE_LHS-1:0] paddr;     // APB address
// leda NTL_CON37 on
// leda NTL_CON13C on
   input                            pwrite;    // APB write/read
   input                            penable;   // APB enable
   input                      [7:0] pwdata;    // APB write data bus
   
   output     [`APB_DATA_WIDTH-1:0] prdata;    // APB read data bus

   // -------------------------------------
   // -- Register block interface signals
   // -------------------------------------
   input  [`MAX_APB_DATA_WIDTH-1:0] iprdata;   // Internal read data bus

   output           wr_en;     // Write enable signal
   output           rd_en;     // Read enable signal
   output                           byte_en;   // Active byte lane signal
   output      [ADDR_SLICE_LHS-3:0] reg_addr;  // Register address offset
   output                     [7:0] ipwdata;   // Internal write data bus

   // -------------------------------------
   // -- Local registers & wires
   // -------------------------------------
   
