// -----------------------------------------------------------
// -- Register bit Width macros
// -----------------------------------------------------------
`define   WDT_CR_RW                6

// -----------------------------------------------------------
// -- Register address offset macros
// -----------------------------------------------------------
`define   WDT_CR_OFFSET            0
`define   WDT_TORR_OFFSET          1
`define   WDT_CCVR_OFFSET          2
`define   WDT_CRR_OFFSET           3
`define   WDT_STAT_OFFSET          4
`define   WDT_EOI_OFFSET           5
`define   WDT_VID_OFFSET           6

`define   WDT_PERIPH_ID_OFFSET      `WDT_NUM_REGISTERS - 1
`define   WDT_VERSION_ID_OFFSET     `WDT_NUM_REGISTERS - 2
`define   WDT_CONFIGID_REG_1_OFFSET `WDT_NUM_REGISTERS - 3 
`define   WDT_CONFIGID_REG_2_OFFSET `WDT_NUM_REGISTERS - 4 
`define   WDT_CONFIGID_REG_3_OFFSET `WDT_NUM_REGISTERS - 5 
`define   WDT_CONFIGID_REG_4_OFFSET `WDT_NUM_REGISTERS - 6 
`define   WDT_CONFIGID_REG_5_OFFSET `WDT_NUM_REGISTERS - 7 

// -----------------------------------------------------------
// -- Reset pulse length macros
// -----------------------------------------------------------
`define   WDT_RPL_0                8'd1
`define   WDT_RPL_1                8'd3
`define   WDT_RPL_2                8'd7
`define   WDT_RPL_3                8'd15
`define   WDT_RPL_4                8'd31
`define   WDT_RPL_5                8'd63
`define   WDT_RPL_6                8'd127
`define   WDT_RPL_7                8'd255

