   presetn,
   // clcis_apb_wdt_biu interface
   wr_en,
   rd_en,
   byte_en,
   reg_addr,
   ipwdata,
   iprdata,
   // Interrupt and system reset interface
   top,
   restart,
   wdt_en,
   eoi_en,
   rpl,
   rmod,
   intr,
   cnt
   );

