`endprotected128
input                               pclk;           // APB clock 
   input                               presetn;        // APB async reset
   input             wr_en;          // write enable
   input             rd_en;          // read enable
   input                               byte_en;        // active byte lane
   input     [`WDT_ADDR_SLICE_LHS-3:0] reg_addr;       // register address offset
   input     [7:0]                     ipwdata;        // internal APB write data
   output    [`MAX_APB_DATA_WIDTH-1:0] iprdata;        // internal APB read data
              
   input          [`WDT_CNT_WIDTH-1:0] cnt;            // watchdog counter value
   input                               intr;           // watchdog interrupt
   output         [`WDT_CNT_WIDTH-1:0] top;            // watchdog timeout period
   output                              restart;        // watchdog counter restart
   output                              wdt_en;         // watchdog timer enable
   output                              eoi_en;         // end of interrupt enable
   output                        [7:0] rpl;            // reset pulse length
   output                              rmod;           // output response mode

   // ------------------------------------------------------
   // -- Register enable (select) wires
   // ------------------------------------------------------
   
