module M2_clcis_apb_wdt_isrc
  (
   // Inputs
   pclk,
   presetn,
   top,
   restart,
   wdt_en,
   eoi_en,
   rpl,
   rmod,
   speed_up,
   scan_mode,
   // Outputs
   cnt,
   intr,
   sys_rst
   );


   input                       pclk;       // APB clock
   input           presetn;    // APB active low async reset
   input  [`WDT_CNT_WIDTH-1:0] top;        // timeout period
   input                       restart;    // WD counter restart
   input                       wdt_en;     // WDT enable
   input                       eoi_en;     // EOI enable
   input  [7:0]                rpl;        // reset pulse length
   input                       rmod;       // output response mode
   input                       speed_up;   // test speed up signal
   input                       scan_mode;  // scan signal

   output [`WDT_CNT_WIDTH-1:0] cnt;        // counter value
   output            intr;       // interrupt
   output                      sys_rst;    // system reset

   
`protected128
