module M2_clcis_apb_wdt
  (
   // Inputs
   pclk,
   presetn,
   penable,
   pwrite,
   pwdata,
   paddr,
   psel,
   speed_up,
   scan_mode,
   // Outputs
   wdt_intr,
   wdt_sys_rst_n,
   prdata
   );
   input                           pclk;          // APB clock
   input                           presetn;       // APB active low async reset


   input                           penable;       // strobe signal
   input                           pwrite;        // write enable
   //leda NTL_CON13C off
   //LMD: Non driving port.
   //LJ : Only 8 bits of pwdata is used to write data into the registers.
   //     So the remaining bits will not driving any signals.
   //leda NTL_CON37 off
   //LMD: Signal/Net must read from the input port in module
   //LJ : Only 8 bits of pwdata is used to write data into the registers.
   //     So the remaining bits will not driving any signals.
   input     [`APB_DATA_WIDTH-1:0] pwdata;        // write data bus
   //leda NTL_CON13C on
   //leda NTL_CON37 on

   //leda NTL_CON37 off
   //LMD: Signal/Net must read from the input port in module
   //LJ : LSB bit of the paadr is not used in this configuration.
   //     paddr[1:0] is used to select byte enable signal.
   //     IN APB_DATA_WIDTH=32 configuration, all four bytes of a 32 bit
   //     register is enabled. Hence the LSB two bits are not used in this configuration.
   input [`WDT_ADDR_SLICE_LHS-1:0] paddr;         // address bus
   //leda NTL_CON37 on

   input                           psel;          // APB peripheral select
   input                           speed_up;      // test speed up signal
   input                           scan_mode;     // scan signal
   
   output                          wdt_intr;      // active high interrupt
                                                  // reset
   output                          wdt_sys_rst_n; // active low system
                                                  // reset
   output    [`APB_DATA_WIDTH-1:0] prdata;        // read data bus

   
`protected128
