module M2_swerv_subsys_DW_axi_bcm06 (
    clk,
    rst_n,
    init_n,
    push_req_n,
    pop_req_n,
    diag_n,
    ae_level,
    af_thresh,
    we_n,
    empty,
    almost_empty,
    half_full,
    almost_full,
    full,
    error,
    wr_addr,
    rd_addr,
    wrd_count,
    nxt_empty_n,
    nxt_full,
    nxt_error
    );

`protected128
PG]/O;NS#T<YNT%) O/V<#@Y::B$\BY?33SD$ZM;XEY+7P>:1[7.L7)>NO;E-J)&J
P.=UA[J[O250=,@K_#=;,> :#3MIUNK(:WSW#Q&7JKCA2>"JO[S.*Y5<=P2EY?CC(
P;7&!R!9S3( , QA;6*P&;/W[&CI.1S)[P?WK\;X=NON!T@J1))^7EM>W'VUV4O X
