module M2_swerv_subsys_DW_axi_arb (
  // Inputs - System.
  aclk_i,
  aresetn_i,
  bus_priorities_i,

  // Inputs - Channel Source.
  lock_seq_i,
  locktx_i,
  unlock_i,
  grant_masked_i,
  request_i,
  use_other_pri_i,
  //bus_grant_lock_i,
  
  // Inputs - Channel Destination.
  valid_i,
  ready_i,
  last_i,
  
  // Outputs - Channel Destination.
  grant_o,
  bus_grant_o,
  grant_p_local_o
);

