module M2_swerv_subsys_DW_axi_mp_addrch (
  aclk_i,
  aresetn_i,




  // Inputs - External Master.
  valid_i,
  payload_i,

  // Outputs - External Master.
  ready_o,

  // Inputs - Slave Ports.
  ready_i,
  aw_shrd_lyr_granted_s_bus_i,
  issued_wtx_shrd_sys_s_bus_i,

  // Outputs - Slave Ports.
  bus_valid_o,
  valid_o,
  mask_valid_o,
  shrd_ch_req_o,
  payload_o,

  // Inputs - Pipeline stage.
  id_rs_i,
  local_slv_rs_i,

  // Inputs - Read Data/Burst Response Channel.
  cpl_tx_i,
  cpl_id_i,

  
  // Outputs - Write Data Channel.
  act_ids_o,
  act_snums_o,

 // Outout - region number
  //region_o,

  
  act_ids_buffer,
  act_ids_rd_buffer_pointer,
  issuedtx_slot_oh_o
);


