module M2_swerv_subsys_DW_axi_mp_drespch (
  // Inputs - System.  
  aclk_i,
  aresetn_i,

  bus_slv_priorities_i,

  // Inputs - External Master.  
  ready_i,
  bus_ready_shrd_i,

  // Outputs - External Master.  
  valid_o,
  bus_valid_shrd_o,
  payload_o,
  payload_icm_o,
    
  // Inputs - Slave Ports.  
  bus_valid_i,
  bus_valid_shrd_i,
  bus_payload_i,
    
  // Outputs - Slave Ports.  
  bus_ready_o,

  // Inputs - Address channel.
  //act_snums_i,
    
  // Outputs - Read address channel.  
  cpl_tx_o,
  cpl_tx_shrd_bus_o,
