module M2_swerv_subsys_DW_axi_mp_wdatach (
  // Inputs - System.
  aclk_i,
  aresetn_i,

  // Inputs - External Master.
  valid_i,
  payload_i,

  // Outputs - External Master.
  ready_o,
  act_ids_buffer_pointer,

  // Inputs - Slave Ports.
  ready_i,

  // Outputs - Slave Ports.
  bus_valid_o,
  valid_o,
  mask_valid_o,
  shrd_ch_req_o,
  payload_o,

  // Inputs - Pipeline stage.
  id_rs_i,
  act_ids_buffer,

  // Inputs  - Write Address Channel.
  act_ids_i,
  act_snums_i,
  issuedtx_slot_oh_i
);


