input aclk_i;    // AXI system clock.
  input aresetn_i; // AXI system reset.

  // Inputs - Channel Source
  input [NUM_VIS_SP-1:0] bus_valid_i;
  input                  shrd_ch_req_i;

  // Outputs - Channel Destination
  //leda NTL_CON33 off
  //LMD: None of the inputs have any effect on net
  //LJ: False Warning
  //leda NTL_CON32 off
  //LMD: Change on net has no effect on any of the outputs
  //LJ: False Warning
  output [NUM_VIS_SP-1:0] bus_valid_o;
  //leda NTL_CON32 on
  //leda NTL_CON33 on
  output                  shrd_ch_req_o;
  
  // Inputs - Channel Destination
  input [NUM_VIS_SP-1:0] bus_ready_i;

  // Inputs - Write Data Channel
  input [NUM_VIS_SP-1:0] bus_wready_i;
  //leda NTL_CON37 off
  //LMD: Signal/Net must read from the input port in module
  //LJ: Depending on paramter W_PL_ARB this signal may not be used
  //leda NTL_CON13C off
  //LMD: non driving port
  //LJ: Depending on paramter W_PL_ARB this signal may not be used
  input [NUM_VIS_SP-1:0] bus_wvalid_i;
  input [NUM_VIS_SP-1:0] bus_wvalid_r_i;
  //leda NTL_CON13C on
  //leda NTL_CON37 on
  input wlast_i;


