** Abstract : Master Port block for the DW_axi interconnect.
**            External AXI masters connect to the DW_axi through the
**            master port block.
**
** ---------------------------------------------------------------------
*/
module M2_swerv_subsys_DW_axi_mp (
  aclk_i,
  aresetn_i,



  r_bus_slv_priorities_i,
  b_bus_slv_priorities_i,



  // READ ADDRESS CHANNEL.


  // Inputs - External Master.
  arvalid_i,
  arpayload_i,

  // Outputs - External Master.
  arready_o,

  // Inputs - Slave Ports.
  bus_arready_i,

  // Outputs - Slave Ports.
  bus_arvalid_o,
  ar_shrd_ch_req_o,
  arpayload_o,


  // READ DATA CHANNEL.

  // Inputs - External Master.
  rready_i,

  // Outputs - External Master.
  rvalid_o,
  rpayload_o,

  // Inputs - Slave Ports.
  bus_rvalid_i,
  bus_rpayload_i,

  // Outputs - Slave Ports.
  bus_rready_o,


  // Inputs - Shared Master Port.
  rcpl_tx_shrd_i,
  rcpl_id_shrd_i,

  // WRITE ADDRESS CHANNEL.


  // Inputs - External Master.
  awvalid_i,
  awpayload_i,

  // Outputs - External Master.
  awready_o,

  // Inputs - Slave Ports.
  bus_awready_i,
  aw_shrd_lyr_granted_s_bus_i,
  issued_wtx_shrd_sys_s_bus_i,

  // Outputs - Slave Ports.
  bus_awvalid_o,
  aw_shrd_ch_req_o,
  awpayload_o,


  // WRITE DATA CHANNEL.

  // Inputs - External Master.
  wvalid_i,
  wpayload_i,

  // Outputs - External Master.
  wready_o,

  // Inputs - Slave Ports.
  bus_wready_i,

  // Outputs - Slave Ports.
  bus_wvalid_o,
  w_shrd_ch_req_o,
  wpayload_o,


  // BURST RESPONSE CHANNEL.

  // Inputs - External Master.
  bready_i,

  // Outputs - External Master.
  bvalid_o,
  bpayload_o,

  // Inputs - Slave Ports.
  bus_bvalid_i,
  bus_bpayload_i,

  // Outputs - Slave Ports.
  bus_bready_o,

  // Inputs - Shared Master Port.
  wcpl_tx_shrd_i,
  wcpl_id_shrd_i

);

