module M2_swerv_subsys_DW_axi_sp_addrch (
  // Inputs - System.
  aclk_i,
  aresetn_i,
  bus_mst_priorities_i,
    
  // Inputs - External Slave.
  ready_i,
  bus_ready_shrd_i,
    
  // Outputs - External Slave.
  valid_o,
  bus_valid_shrd_o,
  payload_o,
    
  // Inputs - Master Ports.
  bus_arvalid_i,
  bus_awvalid_i,

  bus_arvalid_shrd_i,
  bus_awvalid_shrd_i,

  bus_payload_i,
    
  // Outputs - Master Ports.
  bus_ready_o,
  shrd_lyr_granted_o,
    
  // Inputs - Read/Write Address Channel.
  outstnd_txs_fed_i,
  outstnd_txs_nonlkd_i,
  unlocking_tx_rcvd_i,
  bus_grant_arb_i,
  grant_m_local_arb_i,
  lock_i,
    
  // Outputs - Read/Write Address Channel.
  outstnd_txs_fed_o,
  outstnd_txs_nonlkd_o,
  unlocking_tx_rcvd_o,
  lock_o,
  bus_grant_arb_o,
  grant_m_local_arb_o,
    
  // Inputs - Read Data/Burst Response Channel.
  cpl_tx_i,
  cpl_tx_shrd_bus_i,

  // Outputs - Write Data Channel.
  issued_tx_o,
  issued_mstnum_o,
  issued_tx_shrd_slv_oh_o,
  issued_tx_mst_oh_o
);


