*/

module M2_swerv_subsys_DW_axi_sp_lockarb (
  // Inputs - System.
  aclk_i,
  aresetn_i,
  bus_mst_priorities_i,

  // Inputs - Channel Source.
  rreq_i,
  wreq_i,
  tx_cnt_nz_i,

  // Inputs - Channel Destination.
  ready_i,

  // Inputs - Other address channel block.
  outstnd_txs_fed_i,
  outstnd_txs_nonlkd_i,
  unlocking_tx_rcvd_i,
  bus_grant_arb_i,
  grant_m_local_arb_i,
  lock_other_i,
  
  // Outputs - Other address channel block.
  outstnd_txs_fed_o,
  outstnd_txs_nonlkd_o,
  unlocking_tx_rcvd_o,
  lock_o,
  bus_grant_arb_o,
  grant_m_local_arb_o,

  // Inputs - Completion channel.
  cpl_tx_i,
  
  // Outputs - Channel Destination.
  grant_o,
  bus_grant_o,
  grant_m_local_o
