  // Inputs - System
  aclk_i,
  aresetn_i,

  // Inputs - Master Ports
  bus_valid_i,
  bus_valid_shrd_i,
  
  // Inputs - Slave Ports (Write address channels)
  issued_slvnum_oh_i,
  issued_mstnum_i,
  bus_ready_shrd_m_i,
  tx_acc_s_i,

  // Inputs - Dedicated W Channels.
  shrd_w_nxt_fb_pend_bus_i,
  
  // Outputs - Slave Port Arbiter
  bus_mst_req_o,

  // Inputs - Slave Port
  bus_valid_shrd_out_i,
  cpl_tx_bus_i
);

