** Created  : Mon May  9 19:49:59 MEST 2005
** Modified : $Date: 2016/02/01 $
** Abstract : Slave Port block for the DW_axi interconnect.
**            External AXI slaves connect to the DW_axi through slave 
**            ports.
**
** ---------------------------------------------------------------------
*/
module M2_swerv_subsys_DW_axi_sp (
  aclk_i,
  aresetn_i,

  ar_bus_mst_priorities_i,
  aw_bus_mst_priorities_i,
  w_bus_mst_priorities_i,

  // READ ADDRESS CHANNEL.
  
  // Inputs - External Slave.
  arready_i,

  // Outputs - External Slave.
  arvalid_o,
  arpayload_o,

  // Inputs - Master Ports.
  bus_arvalid_i,
  bus_arpayload_i,

  // Outputs - Master Ports.
  bus_arready_o,


  // READ DATA CHANNEL.
  
  // Inputs - External Slave.
  rvalid_i,
  rpayload_i,

  // Outputs - External Slave.
  rready_o,
  
  // Inputs - Master Ports.
  bus_rready_i,

  // Outputs - Master Ports.
  bus_rvalid_o,
  r_shrd_ch_req_o,
  rpayload_o,
  
  // Outputs - Shared Slave Port AR.
  rcpl_tx_shrd_o,

  // WRITE ADDRESS CHANNEL.
  
  // Inputs - External Slave.
  awready_i,

  // Outputs - External Slave.
  awvalid_o,
  awpayload_o,

  // Inputs - Master Ports.
  bus_awvalid_i,
  bus_awpayload_i,

  // Outputs - Master Ports.
  bus_awready_o,
  aw_shrd_lyr_granted_o,

  // Top level - Out
  issued_wtx_mst_oh_o,

  // Top level - In
  issued_wtx_mst_oh_i,


  // WRITE DATA CHANNEL.
  
  // Inputs - External Slave.
  wready_i,

  // Outputs - External Slave.
  wvalid_o,
  wpayload_o,

  // Inputs - Master Ports.
  bus_wvalid_i,
  bus_wpayload_i,

  // Outputs - Master Ports.
  bus_wready_o,

  // Inputs - Shared AW channel.
  issued_tx_shrd_i,
  issued_tx_shrd_mst_oh_i,

  // Outputs - Shared W channel.
  shrd_w_nxt_fb_pend_o,

  // BURST RESPONSE CHANNEL.
  
  // Inputs - External Slave.
  bvalid_i,
  bpayload_i,

  // Outputs - External Slave.
  bready_o,

  // Inputs - Master Ports.
  bus_bready_i,

  // Outputs - Master Ports.
  bus_bvalid_o,
  b_shrd_ch_req_o,
  bpayload_o,

  // Outputs - Shared Slave Port AW.
  wcpl_tx_shrd_o
);

