module M2_swerv_subsys_DW_axi_dfltslv(
    // Inputs - System
    aclk_i,                  
    aresetn_i,               
    
    // Inputs - Read address channel signals
    arvalid_i,               
    arid_i,
    arlen_i,
    araddr_i,
    arsize_i,
    arlock_i,
    arburst_i,
    arcache_i,
    arprot_i,

    // Outputs - Read address channel signals
    arready_o,

    // Inputs - Read data channel signals
    rready_i,
      
    // Outputs - Read data channel signals
    rvalid_o,
    rid_o,
    rresp_o,
    rlast_o,
    rdata_o,

    // Inputs - Write address channel signals
    awvalid_i,
    awid_i,
    awlen_i,
    awaddr_i,
    awsize_i,
    awlock_i,
    awburst_i,
    awcache_i,
    awprot_i,


    // Outputs - Write address channel signals
    awready_o,
      
    // Inputs - Write data channel signals
    wvalid_i,
    wlast_i,
    wid_i,
    wdata_i,
    wstrb_i,
    
    // outputs - Write data channel signals
    wready_o,

    // Inputs - write response channel signals
    bready_i,

    // Outputs - write response channel signals
    bvalid_o,
    bid_o,
    bresp_o
   
  );

  //-------------------------------------------------------------------
  // Parameters
  //-------------------------------------------------------------------
  `protected128
