module M2_swerv_subsys_DW_axi_dlock_mux (
  aclk,
  aresetn,  
  dlock_w_m1,
  dlock_id_w_m1,
  dlock_snum_w_m1,
  dlock_r_m1,
  dlock_id_r_m1,
  dlock_snum_r_m1,
  dlock_w_m2,
  dlock_id_w_m2,
  dlock_snum_w_m2,
  dlock_r_m2,
  dlock_id_r_m2,
  dlock_snum_r_m2,
  dlock_w_m3,
  dlock_id_w_m3,
  dlock_snum_w_m3,
  dlock_r_m3,
  dlock_id_r_m3,
  dlock_snum_r_m3,
  dlock_w_m4,
  dlock_id_w_m4,
  dlock_snum_w_m4,
  dlock_r_m4,
  dlock_id_r_m4,
  dlock_snum_r_m4,
  dlock_w_m5,
  dlock_id_w_m5,
  dlock_snum_w_m5,
  dlock_r_m5,
  dlock_id_r_m5,
  dlock_snum_r_m5,
  dlock_w_m6,
  dlock_id_w_m6,
  dlock_snum_w_m6,
  dlock_r_m6,
  dlock_id_r_m6,
  dlock_snum_r_m6,
  dlock_mst,
  dlock_slv,
  dlock_id,
  dlock_wr,
  dlock_irq
);

  input                          aclk;
  input                          aresetn;
  input                          dlock_w_m1;
  input [`AXI_MIDW-1:0]          dlock_id_w_m1;
  input [`AXI_LOG2_NSP1-1:0]     dlock_snum_w_m1;
  input                          dlock_r_m1;
  input [`AXI_MIDW-1:0]          dlock_id_r_m1;
  input [`AXI_LOG2_NSP1-1:0]     dlock_snum_r_m1;
  input                          dlock_w_m2;
  input [`AXI_MIDW-1:0]          dlock_id_w_m2;
  input [`AXI_LOG2_NSP1-1:0]     dlock_snum_w_m2;
  input                          dlock_r_m2;
  input [`AXI_MIDW-1:0]          dlock_id_r_m2;
  input [`AXI_LOG2_NSP1-1:0]     dlock_snum_r_m2;
  input                          dlock_w_m3;
  input [`AXI_MIDW-1:0]          dlock_id_w_m3;
  input [`AXI_LOG2_NSP1-1:0]     dlock_snum_w_m3;
  input                          dlock_r_m3;
  input [`AXI_MIDW-1:0]          dlock_id_r_m3;
  input [`AXI_LOG2_NSP1-1:0]     dlock_snum_r_m3;
  input                          dlock_w_m4;
  input [`AXI_MIDW-1:0]          dlock_id_w_m4;
  input [`AXI_LOG2_NSP1-1:0]     dlock_snum_w_m4;
  input                          dlock_r_m4;
  input [`AXI_MIDW-1:0]          dlock_id_r_m4;
  input [`AXI_LOG2_NSP1-1:0]     dlock_snum_r_m4;
  input                          dlock_w_m5;
  input [`AXI_MIDW-1:0]          dlock_id_w_m5;
  input [`AXI_LOG2_NSP1-1:0]     dlock_snum_w_m5;
  input                          dlock_r_m5;
  input [`AXI_MIDW-1:0]          dlock_id_r_m5;
  input [`AXI_LOG2_NSP1-1:0]     dlock_snum_r_m5;
  input                          dlock_w_m6;
  input [`AXI_MIDW-1:0]          dlock_id_w_m6;
  input [`AXI_LOG2_NSP1-1:0]     dlock_snum_w_m6;
  input                          dlock_r_m6;
  input [`AXI_MIDW-1:0]          dlock_id_r_m6;
  input [`AXI_LOG2_NSP1-1:0]     dlock_snum_r_m6;
  output [`AXI_LOG2_LCL_NM-1:0]  dlock_mst;
  output [`AXI_LOG2_NSP1-1:0]    dlock_slv;
  output [`AXI_MIDW-1:0]         dlock_id;
  output                         dlock_wr;
  output                         dlock_irq;

  
