// APB module specific constant//
`define REG_VID             4'h0
`define REG_HWC             4'h4
`define REG_CMD             4'h8
`define REG_DATA            4'hC
`define COMMAND_EN_BIT      31
`define WR_BIT              30
`define SR_BIT              29
`define MID_BIT_MSB         11
`define CH_ID_BIT           7
`define QOS_REG_OFFSET      3 

module M2_swerv_subsys_DW_axi_apb_regfile (
     pclk,
     presetn,
     wr_en,
     rd_en,
     byte_en,
     reg_addr,
     ipwdata,
     iprdata,
     err_bit,
     data_reg_in,
     data_reg_out,
     qosreg_wr_en,
     qosreg_rd_en,
     qosreg_offset,
     internal_reg_rst,
     command_en,
     command_en_ack
     );

   //----------------------------------------------------
   //---Port declaraion-----------------
   //------------------------------------------------------
     input                              pclk;           //apb clock    
     input                              presetn;        //apb reset
     input                              wr_en;          //write en ,generated from Bus Interface Module
     input                              rd_en;          //read enable, generated from Bus Interface Module      
     input  [3:0]                       byte_en;        //Byte enable,
     input  [`IC_ADDR_SLICE_LHS-2:0]    reg_addr;       //APB register offset
     input  [`MAX_APB_DATA_WIDTH-1:0]   ipwdata;        //Write data from APB BIU 
     output [`MAX_APB_DATA_WIDTH-1:0]   iprdata;        //Internal read data bus
     input                              err_bit;        //Error bit signal genrated from qos command decoder logic
     input  [31:0]                      data_reg_in;    //qos data register input
     //leda NTL_CON33 off
     //LMD: None of the inputs have any effect on net
     //LJ: False Warning
     output [31:0]                      data_reg_out;   //qos data register output
     output                             qosreg_wr_en;   //qos register write en
     //leda NTL_CON33 on
     output                             qosreg_rd_en;   //qos register read en
     output [7:0]                       qosreg_offset;  //qos register offset
     output                             internal_reg_rst;     //APB soft reset
     //leda NTL_CON33 off
     //LMD: None of the inputs have any effect on net
     //LJ: False Warning
     output                             command_en;     //command enable output to aclk domain
     input                              command_en_ack; //command enable acknowledgement from aclk domain
     //leda NTL_CON33 on

   // ----------------------------------------------------------
   // -- local registers and wires
   // ----------------------------------------------------------
   //
   
