 File     : DW_axi_qos_regfile.v
 Created  : Thu Nov 17 13:27:47 MEST 2011
 Revision : $Id: //dwh/DW_ocb/DW_axi/amba_dev/src/DW_axi_qos_regfile.v#5 $
 Modified : $Date: 2016/02/01 $
 Abstract : QOS register Output module
  * Module generated QOS registers signal on output ports
  * Implements read and write operation for QOS registers
            
 ---------------------------------------------------------------------
*/ 
module M2_swerv_subsys_DW_axi_qos_regfile
    (
     aclk,
     aresetn,
     internal_reg_rst,
     wr_en,
     rd_en,
     addr,
     wdata,
     command_en_aclk,
     reg_awqos_m1,
     reg_arqos_m1,
     reg_awqos_m2,
     reg_arqos_m2,
     reg_awqos_m3,
     reg_arqos_m3,
     reg_awqos_m4,
     reg_arqos_m4,
     reg_awqos_m5,
     reg_arqos_m5,
     reg_awqos_m6,
     reg_arqos_m6,
 err_bit, 
  rdata ); 
  
       
       
  //Ports decalration
     input                              aclk; //axi clock
     input                              aresetn; //axi reset
     input                              internal_reg_rst; //soft reset
     input                              wr_en; //wr enable signal for qos register--sync with aclk
     input                              rd_en; //read enable signal for qos register--sync with aclk
     input  [7:0]                       addr ; //qos register offset--decoded by commonad regiter values
     //leda NTL_CON33 off
     //LMD:  None of the inputs have any effect on net
     //LJ: in lower configs some of the bits may not be used
     //leda NTL_CON37 off
     //LMD: Module must read from input port 
     //LJ: in lower configs some of the bits may not be used
     //leda NTL_CON13C off
     //LMD: non driving port
     //LJ: in lower configs some of the bits may not be used
     input  [31:0]                      wdata; //data register content to be written on qos regs
     //leda NTL_CON13C on
     //leda NTL_CON37 on
     input                              command_en_aclk; //aclk synced version of command_en
     
     output [`AXI_QOSW-1:0]           reg_awqos_m1;
     output [`AXI_QOSW-1:0]           reg_arqos_m1;
  
     output [`AXI_QOSW-1:0]           reg_awqos_m2;
     output [`AXI_QOSW-1:0]           reg_arqos_m2;
  
     output [`AXI_QOSW-1:0]           reg_awqos_m3;
     output [`AXI_QOSW-1:0]           reg_arqos_m3;
  
     output [`AXI_QOSW-1:0]           reg_awqos_m4;
     output [`AXI_QOSW-1:0]           reg_arqos_m4;
  
     output [`AXI_QOSW-1:0]           reg_awqos_m5;
     output [`AXI_QOSW-1:0]           reg_arqos_m5;
  
     output [`AXI_QOSW-1:0]           reg_awqos_m6;
     output [`AXI_QOSW-1:0]           reg_arqos_m6;
  
  
  
  
  
  
  
  
  
  
  

     output                            err_bit;
     output [31:0]                     rdata ; 
     //leda NTL_CON33 on
 //wire and register declaration 
 
