module M2_swerv_subsys_DW_axi_apbif (
     pclk,
     presetn,
     penable,
     psel,
     pwrite,
     paddr,
     pwdata,
     aclk,
     aresetn,
  
     reg_awqos_m1,
     reg_arqos_m1,
  
     reg_awqos_m2,
     reg_arqos_m2,
     reg_awqos_m3,
     reg_arqos_m3,
     reg_awqos_m4,
     reg_arqos_m4,
     reg_awqos_m5,
     reg_arqos_m5,
     reg_awqos_m6,
     reg_arqos_m6,
      prdata
 );
input                           pclk;
input                           presetn;
input                           penable;
input                           psel;
input                           pwrite;
//leda NTL_CON13C off
//LMD: non driving port Range
//LJ: Only bits required for register addressing are used. Rest bits are only present for interface consistency.
//leda NTL_CON37 off
//LMD: Signal/Net must read from the input port
//LJ: Only bits required for register addressing are used. Rest bits are only present for interface consistency.
input   [`APB_ADDR_WIDTH-1:0]   paddr;
//leda NTL_CON13C on
//leda NTL_CON37 on
input   [`APB_DATA_WIDTH-1:0]   pwdata;
input                           aclk;
input                           aresetn;
output  [`APB_DATA_WIDTH-1:0]   prdata;
   
   
   
   
   
   
   
   
   
   
   
   
   
   
   
   
     output  [`AXI_QOSW-1: 0]       reg_awqos_m1;
     output  [`AXI_QOSW-1: 0]       reg_arqos_m1;
  
    output  [`AXI_QOSW-1: 0]        reg_awqos_m2;
    output  [`AXI_QOSW-1: 0]        reg_arqos_m2;
     output  [`AXI_QOSW-1: 0]       reg_awqos_m3;
     output  [`AXI_QOSW-1: 0]       reg_arqos_m3;
     output  [`AXI_QOSW-1: 0]       reg_awqos_m4;
    output  [`AXI_QOSW-1: 0]        reg_arqos_m4;
    output  [`AXI_QOSW-1: 0]        reg_awqos_m5;
    output  [`AXI_QOSW-1: 0]        reg_arqos_m5;
    output  [`AXI_QOSW-1: 0]        reg_awqos_m6;
   output  [`AXI_QOSW-1: 0]         reg_arqos_m6;


