module M2_swerv_subsys_DW_axi_qos_req_filter (

aclk_i                               ,
aresetn_i                            ,

reg_regulation_enable_i              ,
reg_peak_rate_i                      ,
//grant_i                              ,

req_i                                ,
slv_granted_pulse_i                  ,
valid_token_i                        ,
regulation_enabled_i                 ,
next_token_i                         , 

req_o                                ,
req_wire_o
);

