        clk,
        rst_n,
        init_n,
        inc_req_n,
        other_addr_g,
        word_count,
        empty,
        almost_empty,
        half_full,
        almost_full,
        full,
        error,
        this_addr,
        this_addr_g,
        next_word_count,
        next_empty_n,
        next_full,
        next_error,

        test
        );

