   // Outputs
   //awready,
   wready, 
                    bid, 
                    bresp, 
                    bvalid, 
                    cmd_queue_wd, 
                    push_cmd_queue_n, 
                    pop_resp_n,
                    write_buffer_wd, 
                    push_write_buffer_n, 
                    rid, 
                    rdata, 
                    rresp, 
                    rlast,
                    rvalid, //arready,
                    pop_data_int_n,
                    // Inputs
                    awid, 
                    awaddr, 
                    awlen, 
                    awsize, 
                    awburst, 
                    //   awlock,
                    //   awcache,
                    //   awprot,
                    awvalid, 
                    //   `ifdef X2P_AXI3_INTERFACE
                    //   wid,
                    //   `endif
                    wdata, 
                    wstrb, 
                    wlast, 
                    wvalid, 
                    bready, 
                    cmd_queue_rdy_n,
                    response_avail_n, 
                    pop_resp_word, 
                    write_buff_rdy_n, 
                    arid, 
                    araddr,
                    arlen, 
                    arsize, 
                    arburst,
                    //   arlock,
                    //   arcache,
                    //   arprot,
                    arvalid, 
                    rready,
                    arstatus_int, 
                    arid_int, 
                    arlast_int, 
                    ardata_int, 
                    arvalid_int_n
                    );
