module M2_swerv_sync_DW_axi_x2p_bcm06 (
    clk,
    rst_n,
    init_n,
    push_req_n,
    pop_req_n,
    diag_n,
    ae_level,
    af_thresh,
    we_n,
    empty,
    almost_empty,
    half_full,
    almost_full,
    full,
    error,
    wr_addr,
    rd_addr,
    wrd_count,
    nxt_empty_n,
    nxt_full,
    nxt_error
    );

`protected128
PV&*LL]:A1:KIEZ'+_!JM4SEZM[954NP%6M(R(\07H#'?1&C\9CB^I*O7D.!5PI6[
P VNRW</HQ3O'<Z[@95[]RJB'QW/M9LNIR^)3-9KM0SF7;1 +'%)K;?2UGMX$X0S/
PBL?0Y9:^8IIO687 1NU)5YVP; >-,+T[&Y#%AH%_6I&/9"Z&3=E,+P=<AA+^H66;
