module M2_swerv_sync_s_DW_axi_x2p_bcm06 (
    clk,
    rst_n,
    init_n,
    push_req_n,
    pop_req_n,
    diag_n,
    ae_level,
    af_thresh,
    we_n,
    empty,
    almost_empty,
    half_full,
    almost_full,
    full,
    error,
    wr_addr,
    rd_addr,
    wrd_count,
    nxt_empty_n,
    nxt_full,
    nxt_error
    );

`protected128
PHL8+;('2*<"#K+'R_#I>-Q:@3=3%9G=X^X 4*T#UDEU?;._2=%!,_(JKNX?KRX:A
PY4M1G- NO2[047?GQ-$*&B3'28.(5,$QP]H3; 6F<9?S!X-]?@UC5\65PFO<+IQ$
P@I(G49N!?HAY3QSV#<_V)=O!3L#%K$O3.R0(/L_!)=5@R!<\61856[OB[VU^ZIR=
