/*********************************************************************/
/*                                                                   */
/*                  X2P_APB control module                           */
/*                                                                   */
/*                                                                   */
/*********************************************************************/

module M2_swerv_sync_s_DW_axi_x2p_s_control(/*AUTOARG*/
  // Outputs
  push_read_buffer_n, 
                            rd_error, 
                            enable_pack, 
                            last_push_read, 
                            clr_rd_data_reg, 
                            penable, 
                            psel_en, 
                            pwrite, 
                            pop_write_buff_n, 
                            pop_cmd_queue_n, 
                            push_rsp_buff_n, 
                            error, 
                            incr_addr, 
                            set_addr, 
                            incr_base_addr, 
                            base_incr_value,
                            save_id, 
                            set_data, 
                            next_apb_wd_sel, 
                            update_address, 
                            // Inputs
                            clk, 
                            rstn, 
                            cmd_queue_wd, 
                            cmd_queue_empty, 
                            write_buffer_last, 
                            next_write_buff_empty, 
                            selected_strobes, 
                            dcd_error, 
                            read_buffer_full, 
                            pready, 
                            pslverr,
                            next_first_strobes,
                            last_strobes, 
                            resp_rdy_n
                            );

   input clk;
   input rstn; 
  // these are used for the command queue
  //leda NTL_CON13C off
  //LMD: non driving port
  //LJ: Not all the bits of this signal are used in this module. (For example the AXI-ID bits and the higher addr MSbits are unused).
  input [`X2P_CMD_QUEUE_WIDTH:0] cmd_queue_wd;
  //leda NTL_CON13C on
  input                          cmd_queue_empty;
 
  //the write buffer
  input                       write_buffer_last;  // include the WSTRB and LAST
  input                       next_write_buff_empty;

// coming from the  data unpacking module
// strobes set for current APB word to write 
// address decode error from the address generation
   input [(`X2P_APB_DATA_WIDTH/8)-1:0] selected_strobes; // strobes for current APB word to write 
// address decode error from the address generation
   input                      dcd_error;

   // interface to the read buffer
   input                      read_buffer_full;
   output                     push_read_buffer_n;
   
`protected128
PTJ/A6*1^L[987@?97 "[!:V!)&A&\-R,SK3L-'+@?7=2N^8>Z*NHTB5,O/#HG5*7
P+XRY%8Z,5]E%C4:T973NFU$U)ZBT8!*-%,J[K$9 @8R%\2"@ QH5BM\N^.CE<_6$
PZ3N[4,4-]UR%@96CX)7V=&&C"HZ 9TV>C21>8H,1 Y&^"'4!YB=BD++9#-GLL.LS
`endprotected128
output                     rd_error;  
   
   // issues an update in the read buffer packer
   output                     enable_pack;
   output                     last_push_read;
   output                     clr_rd_data_reg;
      
 // from the APB
   input                      pready;
   input                      pslverr;

   // the index pointing to the firstf non-zero strobes
   input [7:0]                next_first_strobes;
   // points to the first of the last  0'd APB strobes
   input [7:0]                last_strobes;
   
   
   // to the APB
   output                     penable;
   output                     psel_en;    // this will enable the slect
   output                     pwrite;
   

   // to pop the next write data word
   output                     pop_write_buff_n;
   // pop the cmd queue
   output                     pop_cmd_queue_n;
   // for pushing into the response buffer
   input                      resp_rdy_n;
   output                     push_rsp_buff_n;
   output                     error;
// to address generator to incriment address
   output                     incr_addr;   // incriment address
   output                     set_addr;    // set in th epopped address
   
`protected128
P*0Y<+ESPT6CWH7E<HRMHN_T?8_+42[055\#GY!\<2YHX^%=#P+T18>KQ_KG"3++V
P,$]W<*2F4FCF+Y;&"+E31MJ[YXMNH:KE,+/>EP[+ZNWC//2QU6-P@]?.TNWLHEGU
`endprotected128
output                     incr_base_addr; // incriments per AXI beat
   output [`X2P_MAX_AXI_SIZE-1:0] base_incr_value; // used while popping the write buff
   output                    save_id;  // time to save he cmd_id
   
   // indicates the data is to be set
   output                    set_data;
   
   // this will count the APB words
   output [7:0]              next_apb_wd_sel;
   output                    update_address;


   
