module M2_swerv_sync_s_DW_axi_x2p_s_response(/*AUTOARG*/
   // Outputs
   resp_id, resp_status, push_n,
   // Inputs
   clk, rstn, wr_error, push_req_n, cmd_id, resp_rdy_n, save_id
   );

   input clk; 
   input rstn; 
  
   input wr_error;
   input push_req_n;
   input [`X2P_AXI_SIDW-1:0] cmd_id;      // this is right from the cmd queue
   input resp_rdy_n;
   input save_id;
   
   output [`X2P_AXI_SIDW-1:0] resp_id;
   output resp_status;
   output push_n;

   
