module M2_swerv_DW_apb_timers (

  pclk,
                      presetn,
                      penable,
                      psel,
                      pwrite,
                      paddr,
                      pwdata,
                      scan_mode,
                      timer_1_clk,
                      timer_2_clk,
                      timer_1_resetn,
                      timer_2_resetn,
                      timer_en,
                      timer_intr_flag,
                      prdata
                      );
  input                                           pclk;
  input                                           presetn;
  input                                           penable;
  input                                           psel;
  input                                           pwrite;
  input [`TIM_ADDR_SLICE_LHS:0]                   paddr;        
  input [`APB_DATA_WIDTH-1:0]                     pwdata;
  input                                           scan_mode; 
  input                                           timer_1_clk;
  input                                           timer_1_resetn;
  //you must ensure that the clocks are stopped whenever the timer is disabled.
  input                                           timer_2_clk;
  input                                           timer_2_resetn;
  //you must ensure that the clocks are stopped whenever the timer is disabled.
  //you must ensure that the clocks are stopped whenever the timer is disabled.
  //you must ensure that the clocks are stopped whenever the timer is disabled.
  //you must ensure that the clocks are stopped whenever the timer is disabled.
  //you must ensure that the clocks are stopped whenever the timer is disabled.
  //you must ensure that the clocks are stopped whenever the timer is disabled.
  output [`NUM_TIMERS-1:0]                        timer_en;
  output                                          timer_intr_flag;
  output [`APB_DATA_WIDTH-1:0]                    prdata;

//
// Internal Wiring
//


//
// "bus_current_value" contains the current value of each timer
// Each timer contributes 32 bits to this bus
//
  
