// //reuse-pragma attr CheckExpr[(@A2X_PP_MODE==0) && (@A2X_BRESP_MODE==1) && (@A2X_AHB_SPLIT_MODE==0) && (@A2X_BLW==8)] {@A2X_WD_FIFO_DEPTH<=256}

