module M2_mcu_h2x_DW_axi_a2x_bcm06 (
    clk,
    rst_n,
    init_n,
    push_req_n,
    pop_req_n,
    diag_n,
    ae_level,
    af_thresh,
    we_n,
    empty,
    almost_empty,
    half_full,
    almost_full,
    full,
    error,
    wr_addr,
    rd_addr,
    wrd_count,
    nxt_empty_n,
    nxt_full,
    nxt_error
    );

`protected128
P$^1<[_&K%Y:>Y/FUJ:<*UUR6&Q%*2\\8TJ7@<"V_W8""BVE) #';;FA0+$AF9 /Q
P5"O>GQ3S^]R4,1Z=C6D%+"]GC426]6GWU7G)GFB".R"TT#9ZM2R!H#\=,/!_0( ?
PR^Y[!D50OT%XO 6[Z!+<*S?P:+CXP4.E61"_V _283+AM.1QO>$_2,XWY@SK&]!A
PULD-03(%$Y(>=HC2H?R!8-R8$QS/%60TZBD9,+*Z:B)]1 &=?4L0Z@QS/KK,8OKZ
