input                                    clk;
  input                                    resetn;

  input                                    hwrite;
  input                                    hsel;
  input                                    hready;
  input                                    htrans_nseq;
  input                                    htrans_seq;
  input                                    htrans_idle;
  input                                    hid_valid;

  input                                    recall_vld;       
  input                                    rid_valid;       // ID Valid
  input                                    rlast;

  input  [`A2X_HBLW-1:0]                   hburst_i;
  //leda NTL_CON12 off
  //LMD: Undriven net 
  //LJ: Signal unused in certain configurations
  //leda NTL_CON12C off
  //LMD: Undriven port
  //LJ: Port is unused in certain configurations
  //leda NTL_CON18 off
  //LMD: There is output port, but it is not connected internally
  //LJ:  Port is unused in certain configurations
  //leda NTL_CON38 off
  //LMD: Output is never set
  //LJ:  Output Port is unused in certain configurations
  output [`A2X_HBLW-1:0]                   hburst_o;
  output                                   hburst_vld_o;
  //leda NTL_CON38 on 
  //leda NTL_CON18 on
  //leda NTL_CON12C on
  //leda NTL_CON12 on

  output                                   r_hready_resp;   // Read ID Response
  output                                   r_split_resp;
  output                                   r_retry_resp;
  output                                   r_error_resp;
  output                                   r_hsplit; 

  // AXI read request    
  //leda NTL_CON33 off
  //LMD: None of the inputs have any effect on net
  //LJ : These nets are used to connect the logic under certain configuration.
  //     But this may not drive some of the nets. This will not cause any functional issue.
  input                                    arready;      // AXI read ready             
  //leda NTL_CON33 on
  output                                   arvalid; 
                      
  // AXI read response & read data                       
  input                                    rrvalid;      // AXI read response valid       
  output                                   rready;
  input                                    rresp_err;    // Read Reponse Error
  output                                   flush;
  output                                   busy;

