`endprotected128
input                                    clk;
  input                                    resetn;

  input                                    hsel;         // AHB Select  
  input                                    hready;       // AHB Select  
  input                                    hready_resp_i;
  input                                    hwrite;       // AHB Select  
  input  [`A2X_HBLW-1:0]                   hburst;       // AHB burst             
  input  [1:0]                             htrans;       // AHB address phase     
  input                                    hmastlock; 
  input  [`A2X_HBLW-1:0]                   hburst_dp;  
  input  [2:0]                             hsize_dp;  
  input  [A2X_AW_PYLD_W-1:0]               ha_pyld;

  input  [A2X_PP_DW-1:0]                   hwdata;       // AHB write data        
  input  [A2X_WSBW-1:0]                    hwdata_sb;    // AHB Write Data Sideband Bus

  //leda NTL_CON12 off
  //LMD: Undriven net 
  //LJ: Signal unused in certain configurations
  //leda NTL_CON12C off
  //LMD: Undriven port
  //LJ: Port is unused in certain configurations
  //leda NTL_CON18 off
  //LMD: There is output port, but it is not connected internally
  //LJ:  Port is unused in certain configurations
  output                                   w_hready_resp; // AHB Write Response
  output                                   w_split_resp;
  output                                   w_retry_resp;
  output                                   w_error_resp;
  //leda NTL_CON18 on
  //leda NTL_CON12C on
  //leda NTL_CON12 on
  //leda NTL_CON12 off
  //LMD: Undriven net 
  //LJ: Signal unused in certain configurations
  //leda NTL_CON12C off
  //LMD: Undriven port
  //LJ: Port is unused in certain configurations
  //leda NTL_CON38 off
  //LMD: Output is never set
  //LJ:  Output Port is unused in certain configurations
  output [A2X_NUM_AHBM-1:0]                w_hsplit; 
  //leda NTL_CON38 on 
  //leda NTL_CON12C on
  //leda NTL_CON12 on

  // AXI Write Request   
  //leda NTL_CON33 off
  //LMD: None of the inputs have any effect on net 
  //LJ: False Warning
  input                                    awready;    // AXI write ready             
  //leda NTL_CON33 on
  output                                   awvalid;    // AXI write command valid        
  output [A2X_AW_PYLD_W-1:0]               aw_pyld;    // AXI write payload
                      
  // AXI read response & read data                       
  input                                    wready;     // AXI Write ready             
  output                                   wvalid;     // AXI Write response valid       
  output [A2X_W_PYLD_W-1:0]                w_pyld;     // AXI Write Payload

  // AXI write response                                  
  input                                    bvalid;     // AXI write response valid      
  output                                   bready;     // AXI write response ready            
  input [A2X_B_PYLD_W-1:0]                 b_pyld;     // AXI write response Payload   

  input                                    lk_req;
  input                                    unlk_req;
  input                                    lk_grant;
  input                                    lk_seq;
  input                                    unlk_grant;
  input                                    unlk_grant_d;
  //leda NTL_CON33 off
  //LMD: None of the inputs have any effect on net 
  //LJ: False Warning
  input                                    unlk_cmp;
  input                                    unlk_seq;
  //leda NTL_CON33 on
  input [A2X_AW_PYLD_W-1:0]                unlk_aw_pyld;
  input [A2X_W_PYLD_W-1:0]                 unlk_w_pyld;

  output                                   busy;
  output                                   w_buf_full;

  //*************************************************************************************
  //Signal Decelaration
  //******************************************************************************** on*****
  
