input                                    clk;
  input                                    resetn;

  input                                    hsel;
  input                                    hwrite;
  input                                    hready;
  input                                    hid_valid;
  input                                    hmastlock;
  input  [`A2X_HBLW-1:0]                   hburst;       // AHB burst             
  input  [1:0]                             htrans;       // AHB address phase     
  input  [`A2X_HBLW-1:0]                   hburst_dp;    // AHB burst             

  //leda NTL_CON33 off
  //LMD: None of the inputs have any effect on net
  //LJ : These nets are used to connect the logic under certain configuration.
  //     But this may not drive some of the nets. This will not cause any functional issue.
  input                                    bf_timeout; 
  //leda NTL_CON33 on

  output                                   hw_ebt;
  output                                   hincr_last;
  output                                   os_w_o; 
  output                                   hw_nbuf;

  input  [3:0]                             cache_i; 
  input  [31:0]                            alen_i;
  input  [3:0]                             wrap_ub_len_i;

  output                                   awvalid;
  //leda NTL_CON12 off
  //LMD: Undriven net 
  //LJ: Signal unused in certain configurations
  //leda NTL_CON12C off
  //LMD: Undriven port
  //LJ: Port is unused in certain configurations
  //leda NTL_CON18 off
  //LMD: There is output port, but it is not connected internally
  //LJ:  Port is unused in certain configurations
  //leda NTL_CON38 off
  //LMD: Output is never set
  //LJ:  Output Port is unused in certain configurations
  output [A2X_BLW-1:0]                     alen_o;
  //leda NTL_CON38 on 
  //leda NTL_CON18 on
  //leda NTL_CON12C on
  //leda NTL_CON12 on

  output                                   wvalid;
  output                                   wlast;

  output                                   bready;      // AXI PP B Channel
  input                                    bvalid;
  input                                    bid_valid;
  input  [`A2X_BRESPW-1:0]                 bresp;

  //leda NTL_CON18 off
  //LMD: There is output port, but it is not connected internally
  //LJ:  Port is unused in certain configurations
  //leda NTL_CON38 off
  //LMD: Output is never set
  //LJ:  Output Port is unused in certain configurations
  //leda NTL_CON12 off
  //LMD: Undriven net 
  //LJ: Signal unused in certain configurations
  //leda NTL_CON12C off
  //LMD: Undriven port
  //LJ: Port is unused in certain configurations
  output                                   w_hready_resp;  // AHB Response
  output                                   w_split_resp;
  output                                   w_error_resp;
  output                                   w_retry_resp;
  output                                   w_hsplit;
  //leda NTL_CON12C on
  //leda NTL_CON12 on
  //leda NTL_CON38 on 
