   // Outputs
   active_as, alast_as, pyld_o, onek_exceed, 
   ws_addr, ws_alen, ws_size, ws_resize, ws_fixed, wrap, 
   // Inputs
   clk, resetn, a_ready_i, bypass_ws,
   a_fifo_empty, sp_os_fifo_vld, active_ac, alast_ac, pyld_i, 
   snf_pyld_i, trans_en
   );

