input                                      clk;              // clock
  input                                      resetn;           // asynchronous reset


  input                                      bypass_ws;
  // Handshaking
  input                                      a_ready_i;
  input                                      a_fifo_empty;
  input                                      sp_os_fifo_vld;
  input                                      alast_ac;
  //leda NTL_CON33 off
  //LMD: None of the inputs have any effect on net
  //LJ : These nets are used to connect the logic under certain configuration.
  //     But this may not drive some of the nets. This will not cause any functional issue.
  input                                      active_ac;        // Address Calculator Active
  output                                     active_as;        // Address Splitter Active
  //leda NTL_CON33 on
  output                                     alast_as;
  output                                     onek_exceed;      // 1K Boundary Exceed for AHB

  output [A2X_AW-1:0]                        ws_addr;          // Wrap Splitter output Address
  output [BLW_AS-1:0]                        ws_alen;          // Wrap Splitter output Length
  output [`A2X_BSW-1:0]                      ws_size;          
  output                                     wrap;
  output [`A2X_RSW-1:0]                      ws_resize; 
  output                                     ws_fixed;

  input  [A2X_PYLD_I-1:0]                    pyld_i;
  output [A2X_PYLD_O-1:0]                    pyld_o;

  input  [A2X_WSNF_PYLD_W-1:0]               snf_pyld_i;
  input                                      trans_en; 
  
