input                                      clk;         // clock
  input                                      resetn;      // asynchronous reset

  input                                      buf_mode;     
  input  [31:0]                              max_len; 
  input  [2:0]                               rs_ratio;
  input  [2:0]                               asize_pp;

  // Handshaking
  //leda NTL_CON33 off
  //LMD: None of the inputs have any effect on net
  //LJ : These nets are used to connect the logic under certain configuration.
  //     But this may not drive some of the nets. This will not cause any functional issue.
  input                                      a_ready_i;   // Channel Control
  input                                      active_as; 
  input                                      trans_en;
  //leda NTL_CON33 on
  input                                      a_fifo_empty;
  input                                      sp_os_fifo_vld;
  output                                     active;

  input  [A2X_PYLD_I-1:0]                    pyld_i;      // Payload
  output [A2X_PYLD_O-1:0]                    pyld_o;

  input                                      ds_fixed_decomp;
  input  [BLW_RS-1:0]                        ds_fixed_len;

  input  [A2X_WSNF_PYLD_W-1:0]               snf_pyld_i; 
  input                                      ws_fixed;

  output [A2X_BLW-1:0]                       len_o; 
  output [A2X_BLW-1:0]                       nxt_len_o; 
  output                                     alast_o;
  output                                     w_snf_pop_en;

