`endprotected128
input                                       clk_pp;
  input                                       resetn_pp;

  input                                       clk_sp;
  input                                       resetn_sp;

  input                                       bypass_aw_ws; 
  // AXI Write Address
  //leda NTL_CON33 off
  //LMD: None of the inputs have any effect on net
  //LJ : These nets are used to connect the logic under certain configuration.
  //     But this may not drive some of the nets. This will not cause any functional issue.
  output                                      awready_pp;             // Primary Port Payload
  //leda NTL_CON33 on
  input                                       awvalid_pp;
  input  [A2X_AW_PYLD_W-1:0]                  aw_pyld_pp;
  input  [A2X_WSNF_PYLD_W-1:0]                snf_pyld_pp;

  input                                       awready_sp;             // Secondary Port Payload
  output                                      awvalid_sp;
  output [A2X_AW_PYLD_W-1:0]                  aw_pyld_sp;
  output                                      awlast_sp;
  
  // Locked Control
  input                                       lock_grant;                 // Locked Control
  input                                       unlock_grant;                 
  input                                       lockseq_cmp;                 
  output                                      os_unlock;                 
  output                                      lock_req_o;
  input                                       lock_req_i;
  output                                      unlock_req_o;
  input                                       unlock_req_i;

  // Software Control
  input                                       wbuf_mode;

  // FIFO Control
  input                                       snf_fifo_push_n;        // FIFO Controls
  output                                      sp_osaw_fifo_push_n;

  output                                      snf_fifo_full;
  input                                       sp_osaw_fifo_full;
  input                                       pp_osaw_fifo_full;
  input                                       b_osw_fifo_valid;
  input                                       b_osw_trans; 

  output [A2X_SP_OSAW_PYLD_W-1:0]             sp_osaw_pyld;          // Resize information - Generated from output of AW FIFO. 

  output                                      aw_sp_active;          // SP AW Channel is not actively generating SP transactions. 
  output                                      aw_push_empty;
  output                                      snf_push_empty;
  output                                      osw_trans;
  output                                      aw_nbuf_sp;

  input                                       pp_rst_n;
  input                                       sp_rst_n;
  input                                       lp_mode;

  //*************************************************************************************
  // Signal Decelaration
  //*************************************************************************************
  //  FIFO Control
  //leda NTL_CON13A off
  //LMD: Non driving internal net.
  //LJ : These are dummy wires used to connect the unconnected ports.
  //     Hence will not drive any nets.
  
