   arready_sp, rbuf_mode, r_osr_trans, 
   r_fifo_len, 
   r_uid_fifo_valid,  bypass_ar_ws, 
   unlock_req_i, lock_req_i, lock_grant, unlock_grant, lockseq_cmp,
   pp_rst_n, sp_rst_n, lp_mode
