  input                                 wready_i;    
  //leda NTL_CON33 on
  input  [A2X_PP_PYLD_W-1:0]            w_pyld_i;

  output                                w_fifo_push_n;
  output [A2X_SP_PYLD_W-1:0]            w_pyld_o;

  input  [A2X_PP_OSAW_PYLD_W-1:0]       rs_pyld_i;

  output [A2X_BLW-1:0]                  wrap_ub_len;

