   r_osr_fifo_empty, r_fifo_len,
   // Inputs
   clk_pp, resetn_pp, clk_sp, resetn_sp, 
   siu_rbuf_mode, 
   bypass_urid_fifo,
   arready_sp, arvalid_sp, arid_sp, rready_pp, 
   rready_pp_lk, 
   rvalid_sp, r_pyld_sp, 
   arlen_sp, 
   arlast_sp, sp_osar_pyld,  
   sp_locked, 
