input                                       clk_sp;
  input                                       resetn_sp;

  input                                       arready_sp;         // SP AR Channel
  //leda NTL_CON33 off
  //LMD: None of the inputs have any effect on net
  //LJ : These nets are used to connect the logic under certain configuration.
  //     But this may not drive some of the nets. This will not cause any functional issue.
  input                                       arvalid_sp;
  input  [`A2X_IDW-1:0]                       arid_sp;
  //leda NTL_CON33 on

  input                                       arlast_sp;         // SP AR Last - Indicates the last SP transaction for a give PP transaction
  input  [A2X_SP_OSAR_PYLD_W-1:0]             sp_osar_pyld;           // Transaction resize Information. 

  //leda NTL_CON33 off
  //LMD: None of the inputs have any effect on net
  //LJ : These nets are used to connect the logic under certain configuration.
  //     But this may not drive some of the nets. This will not cause any functional issue.
  input                                       rready_sp;         // SP R channel
  //leda NTL_CON33 on
  input                                       rvalid_sp;
  input  [A2X_SP_PYLD_W-1:0]                  r_pyld_i;
  output [A2X_R_FIFO_PYLD_W-1:0]              r_pyld_o;
  output                                      r_fifo_push_n;

  //leda NTL_CON33 off
  //LMD: None of the inputs have any effect on net
  //LJ : These nets are used to connect the logic under certain configuration.
  //     But this may not drive some of the nets. This will not cause any functional issue.
  input                                       uid_wr_en;         // Unique RID Control
  //leda NTL_CON33 on
  output                                      uid_fifo_full;
  output                                      uid_fifo_empty;
  output                                      uid_fifo_match;

  input                                       sp_rst_n;

  // **************************************************************************************
  // Signal Decelaration
  // **************************************************************************************
  //leda NTL_CON33 off
  //LMD: None of the inputs have any effect on net
  //LJ : These nets are used to connect the logic under certain configuration.
  //     But this may not drive any net in some other configuration.
  //leda NTL_CON32 off
  //LMD: Change on net has no effect on any of the outputs.
  //LJ : These nets are used to connect the logic under certain configuration.
  //     But this may not drive any net in some other configuration. 
  
