**-------------------------------------------------------------------------------
**                  Architecture Diagram
**-------------------------------------------------------------------------------
**                                  Secondary Port
**
**  |------------------|      |--------------------------|
**  |                  |      |   Write Response Channel |    Write Response Channel
**  |                  |<-----|    DW_axi_a2x_b.v        |<-------------------------
**  |                  |      |--------------------------|
**  |                  |                  ^
**  |                  |                  |
**  |                  |      |--------------------------|
**  |                  |      |   Write Address Channel  |    Write Address Channel
**  |                  |----->|    DW_axi_a2x_aw.v       |------------------------->
**  |                  |      |--------------------------|
**  |                  |                  |
**  |                  |                  V
**  |                  |      |--------------------------|
**  |    AHB-AXI       |----->|    Write Data Channel    |    Write Data Channel
**  | DW_axi_a2x_h2x.v |      |      DW_axi_a2x_w.v      |------------------------->
**  |                  |      |--------------------------|
**  |                  |                  |
**  |                  |                  V
**  |                  |      |--------------------------|
**  |                  |----->|    Read Address Channel  |    Read Address Channel
**  |                  |      |      DW_axi_a2x_ar.v     |------------------------->
**  |                  |      |--------------------------|
**  |                  |                  |
**  |                  |                  V
**  |                  |      |--------------------------|
**  |                  |----->|    Read Data Channel     |    Read Data Channel
**  |                  |      |      DW_axi_a2x_r.v      |------------------------>
**  |------------------|      |--------------------------|
**
**--------------------------------------------------------------------------
*/
module M2_mcu_h2x_DW_axi_a2x (

  //*************************************************************************************
  // Low Power Control
  //*************************************************************************************
                   busy_status,
                   //*************************************************************************************
                   // AHB Interface
                   //*************************************************************************************
                   hclk,
                   hresetn,
                   hsel,
                   hmaster,
                   haddr,
                   hwrite,
                   hmastlock,
                   hburst,
                   htrans,
                   hsize,
                   hprot,
                   hwdata,
                   hready,
                   hready_resp,
                   hresp,
                   hrdata,
                   hsplit,
                   hresize,
                   //*************************************************************************************
                   // AXI Secondary Port Clock & Reset Interface
                   //*************************************************************************************
                   clk_sp,
                   resetn_sp,
                   //*************************************************************************************
                   // AXI Write Address Secondary Port Interface
                   //*************************************************************************************
                   awready_sp,
                   awvalid_sp,
                   awid_sp,
                   // The associated control signals are used to determine the addresses of the remaining transfers in a burst.
                   awaddr_sp,
                   awlen_sp,
                   awsize_sp,
                   awburst_sp,
                   awlock_sp,
                   awcache_sp,
                   awprot_sp,
                   //*************************************************************************************
                   // AXI Write Data Secondary Port Interface
                   //*************************************************************************************
                   wready_sp,
                   wvalid_sp,
                   wlast_sp,
                   wdata_sp,
                   wstrb_sp,
                   //*************************************************************************************
                   // AXI Write Response Secondary Port Interface
                   //*************************************************************************************
                   bready_sp,
                   bvalid_sp,
                   bid_sp,
                   bresp_sp,
                   //*************************************************************************************
                   // AXI Read Address Secondary Port Interface
                   //*************************************************************************************
                   arready_sp,
                   arvalid_sp,
                   arid_sp,
                   araddr_sp,
                   arlen_sp,
                   arsize_sp,
                   arburst_sp,
                   arlock_sp,
                   arcache_sp,
                   arprot_sp,
                   //*************************************************************************************
                   // AXI Read Data Secondary Port Interface
                   //*************************************************************************************
                   rready_sp,
                   rvalid_sp,
                   rlast_sp,
                   rid_sp,
                   rdata_sp,
                   rresp_sp
                   );

  //*************************************************************************************
  //Derived Parameter Decelaration
  //*************************************************************************************
  `protected128
