`endprotected128
input                                       hclk;
  input                                       hresetn;
  input                                       hsel;        // AHB Select
  input  [`A2X_IDW-1:0]                       hmaster;     // AHB Master ID Bus
  input  [A2X_PP_AWIDTH-1:0]                  haddr;       // AHB Address Bus
  input                                       hwrite;      // AHB write indicator
  input                                       hmastlock;   // AHB lock
  input  [`A2X_HBLW-1:0]                      hburst;      // AHB burst
  input                                       hresize;     // AHB Resize Data
  input  [1:0]                                htrans;      // AHB address phase
  input  [`A2X_BSW-1:0]                       hsize;       // AHB size
  input  [`A2X_HPTW-1:0]                      hprot;       // AHB protection
  input  [A2X_PP_DWIDTH-1:0]                  hwdata;      // AHB write data

  input                                       hready;      // AHB ready
  output                                      hready_resp; // AHB ready
  output [`A2X_HRESPW-1:0]                    hresp;       // AHB response
  output [A2X_PP_DWIDTH-1:0]                  hrdata;      // AHB read data
  output [15:0]                               hsplit;      // AHB Split - Dummy Master set to zero


  //-----------------------------AXI Interface------------------------------------------
  

  // AXI write data

  // AXI write response

  // AXI Address Read

  // AXI Read data

  //*************************************************************************************
  // Secondary Port I/O Decelaration
  //*************************************************************************************
  input                                       clk_sp;
  input                                       resetn_sp;

  input                                       awready_sp;
  output                                      awvalid_sp;
  output [`A2X_SP_IDW-1:0]                    awid_sp;
  output [A2X_SP_AWIDTH-1:0]                  awaddr_sp;
  output [A2X_SP_BLWIDTH-1:0]                 awlen_sp;
  output [`A2X_BSW-1:0]                       awsize_sp;
  output [`A2X_BTW-1:0]                       awburst_sp;
  output [`A2X_INT_LTW-1:0]                   awlock_sp;
  output [`A2X_CTW-1:0]                       awcache_sp;
  output [`A2X_PTW-1:0]                       awprot_sp;

  // AXI write data
  input                                       wready_sp;
  output                                      wvalid_sp;
  output                                      wlast_sp;
  output [A2X_SP_DWIDTH-1:0]                  wdata_sp;
  output [A2X_SP_WSTRB_DW-1:0]                wstrb_sp;

  // AXI write response
  output                                      bready_sp;
  input                                       bvalid_sp;
  input [`A2X_SP_IDW-1:0]                     bid_sp;
  input [`A2X_BRESPW-1:0]                     bresp_sp;

  // AXI Read Address
  input                                       arready_sp;
  output                                      arvalid_sp;
  output [`A2X_SP_IDW-1:0]                    arid_sp;
  output [A2X_SP_AWIDTH-1:0]                  araddr_sp;
  output [A2X_SP_BLWIDTH-1:0]                 arlen_sp;
  output [`A2X_BSW-1:0]                       arsize_sp;
  output [`A2X_BTW-1:0]                       arburst_sp;
  output [`A2X_INT_LTW-1:0]                   arlock_sp;
  output [`A2X_CTW-1:0]                       arcache_sp;
  output [`A2X_PTW-1:0]                       arprot_sp;

  // AXI Read data
  output                                      rready_sp;
  input                                       rvalid_sp;
  input                                       rlast_sp;
  input [`A2X_SP_IDW-1:0]                     rid_sp;
  input [A2X_SP_DWIDTH-1:0]                   rdata_sp;
  input [`A2X_RRESPW-1:0]                     rresp_sp;

  // Low Power Control
  output                                      busy_status; 

  //*************************************************************************************
  // Signal Decelaration
  //*************************************************************************************
  //leda NTL_CON13A off
  //LMD: Non driving internal net.
  //LJ : These ports are used to connect the logic under certain configuration.
  //     But this may not drive any net in some other configuration. 
  
