//-----------------------------------------------------------------------------
//
// ABSTRACT:  AXI to GIF Request Module
//
// This module handles the AXI to GIF transaction requests for RD and WR.
//
// Request datapath (req):
//
//                                |----------|
// AXI WDATA ---------------------|fifo_wdata|---------------- GIF mdata
//  Channel                       |__________|                     mwstrb
//
//                                                                 maddr
// AXI AWADDR -|\   |-----------|  |---------|   /-----\           msize
//  Channel    | |__|exc_acc_mon|--|fifo_addr|---|logic|------ GIF mburst
//             | |  |___________|  |_________| | \-----/           mlen
// AXI ARADDR -|/                              |              
//  Channel                                    |
//                                             |
//                                    <to resp data path>
//
//-----------------------------------------------------------------------------
module M2_swerv_sram_DW_axi_gs_req(/*AUTOARG*/
  // Outputs
  awready, 
                     wready, 
                     arready, 
                     maddr, 
                     msize, 
                     mburst, 
                     mlen, 
                     mlast, 
                     mdata, 
                     mwstrb,
                     start_wr_valid, 
                     start_rd_valid, 
                     advance_wr_valid,
                     fid, 
                     flen,
                     fexokay,
                     fexfail, 
                     // Inputs
                     aclk, 
                     aresetn, 
                     awid, 
                     awaddr, 
                     awlen, 
                     awsize, 
                     awburst, 
                     awlock, 
                     awvalid,
                     wdata, 
                     wstrb, 
                     wvalid, 
                     arid, 
                     araddr, 
                     arlen, 
                     arsize, 
                     arburst, 
                     arlock, 
                     arvalid,
                     gclken, 
                     advance_wr, 
                     advance_rd, 
                     req_last_accepted, 
                     sm_high_pwr
                     );


