input  aclk;
input  aresetn;
// Write address channel
input  [`GS_ID-1:0] awid;
input  [`GS_AW-1:0] awaddr;
input  [`GS_BW-1:0] awlen;
input  [2:0] awsize;
input  [1:0] awburst;
input  [1:0] awlock;
input  awvalid;

output awready;
// Write data channel
input  [`GS_DW-1:0] wdata;
input  [`GS_DW/8-1:0] wstrb;
input  wvalid;
output wready;
// Read address channel
input  [`GS_ID-1:0] arid;
input  [`GS_AW-1:0] araddr;
input  [`GS_BW-1:0] arlen;
input  [2:0] arsize;
input  [1:0] arburst;
input  [1:0] arlock;
input  arvalid;


output arready;

// GENERIC SLAVE INTERFACE
// Global
input  gclken;
// Request
output [`GS_AW-1:0] maddr;
output [2:0] msize;
output [1:0] mburst;
output [`GS_BW-1:0] mlen;
output mlast;
output [`GS_DW-1:0] mdata;
output [`GS_DW/8-1:0] mwstrb;



// INTERNAL CONNECTIONS
// Inputs
//input  start_wr;
//input  start_rd;
input  advance_wr;
input  advance_rd;
input  req_last_accepted;
input  sm_high_pwr;
// Outputs to sm
output start_wr_valid;
output start_rd_valid;
output advance_wr_valid;
// Outputs to resp
output [`GS_ID-1:0] fid;
output [`GS_BW-1:0] flen;
output wire fexokay;
output fexfail;


