//-----------------------------------------------------------------------------
//
// ABSTRACT:  AXI to GIF Response Module
//
// This module handles the GIF to AXI transaction responses for RD and WR.
//
// Response datapath (resp):         <from req data path>
//                                        |          |
//                                   |--------| |--------|
//                                   |fifo_bid| |fifo_rid|
//                                   |--------| |--------|
//                                        |__________|
//                                             |                   mready
// AXI BRESP -\                    |---------| | /-----\           svalid
//  Channel    \___________________|fifo_resp|---|logic|------ GIF sdata
//             /                   |_________|   \-----/           sresp
// AXI RDATA -/
//  Channel
//
//
//-----------------------------------------------------------------------------
module M2_swerv_sram_DW_axi_gs_resp(
  // AXI INTERFACE
  // Global
  aclk, 
                      aresetn,
                      // Write Response Channel
                      bid, 
                      bresp, 
                      bvalid, 
                      bready,
                      // Read Data Channel
                      rid, 
                      rdata, 
                      rresp, 
                      rlast, 
                      rvalid, 
                      rready,
                      // GENERIC SLAVE INTERFACE
                      // Global
                      gclken,
                      // Response Channel
                      sdata,
                      mready,
                      // INTERNAL CONNECTIONS
                      // Inputs from sm
                      start_wr, 
                      start_rd, 
                      advance_rd,
                      auto_sresp,
                      auto_svalid,
                      // Inputs from req
                      id,
                      len,
                      exokay, 
                      exfail,
                      resp_cactive, // Output to low_pwr
                      // Outputs to sm
                      advance_rd_ready, 
                      start_wr_ready, 
                      start_rd_ready
                      );
 
  
