`endprotected128
input  aclk;
input  aresetn;
// Write response channel
output [`GS_ID-1:0] bid;
output [1:0] bresp;
output bvalid;
input  bready;
// Read data channel
output [`GS_ID-1:0] rid;
output [`GS_DW-1:0] rdata;
output [1:0] rresp;
output rlast;
output rvalid;
input  rready;

// GENERIC SLAVE INTERFACE
// Global
input  gclken;
// Response Channel
input  [`GS_DW-1:0] sdata;
output mready;


// INTERNAL CONNECTIONS
// Inputs from sm
input  start_wr;
input  start_rd;
input  advance_rd;
input  auto_sresp;
input  auto_svalid;
// Inputs from req
input  [`GS_ID-1:0] id;
input  [`GS_BW-1:0] len;
input  exokay;
input  exfail;
// Outputs to sm
output start_wr_ready;
output start_rd_ready;
output advance_rd_ready;
// Outputs to low_pwr
output resp_cactive;


// ----------------------------------------------------------------------------
// INTERNAL SIGNALS
// ----------------------------------------------------------------------------


