// Revision: $Id: //dwh/DW_ocb/DW_axi_gs/amba_dev/src/DW_axi_gs.v#18 $ 
//
// -------------------------------------------------------------------------
//
// ABSTRACT:  AXI to Generic Interface (GIF) Gasket Top-level
//
// The Generic Slave Gasket design consists of three parts:
//   - a state machine that controls the data flow (sm),
//   - a datapath module that handles AXI to GIF requests (req),
//   - and a datapath module that handles GIF to AXI responses (resp).
//
//
// State machine (sm):
//                                |----|                           mread
// AXI Low-Power -----------------| sm |---------------------- GIF mwrite
//  Channel                       |____|                           mlast
//                                   |                             saccept
//                   <to/from req and resp data path>
//
//
// Request datapath (req):
//
//                                |----------|
// AXI WDATA ---------------------|fifo_wdata|---------------- GIF mdata
//  Channel                       |__________|                     mwstrb
//
//                                                                 maddr
// AXI AWADDR -|\   |-----------|  |---------|   /-----\           msize
//  Channel    | |__|exc_acc_mon|--|fifo_addr|---|logic|------ GIF mburst
//             | |  |___________|  |_________| | \-----/           mlen
// AXI ARADDR -|/                              |              
//  Channel                                    |
//                                             |
//                                         ____|_____
// Response datapath (resp):              |          |
//                                   |--------| |--------|
//                                   |fifo_bid| |fifo_rid|
//                                   |--------| |--------|
//                                        |__________|
//                                             |                   mready
// AXI BRESP -\                    |---------| | /-----\           svalid
//  Channel    \___________________|fifo_resp|---|logic|------ GIF sdata
//             /                   |_________|   \-----/           sresp
// AXI RDATA -/
//  Channel
//
//
// Design Hierarchy
// ------------------------------------------------------
// - gsx                  Top-level
//    - sm                State machine
//    - lpfsm             Low power state machine
//    - req               Request channels (AXI to GIF)
//       - exclusive      Exclusive access monitor
//       - fifo_addr      Request buffer (writes and reads)
//       - fifo_wdata     Write Data buffer
//    - resp              Response channels (GIF to AXI)
//       - fifo_bid       Saves {id, exokay, exfail} of posted writes
//       - fifo_rid       Saves {id, len, exokay, exfail} of posted reads
//       - fifo_resp      Response buffer
//
// Internal signal naming conventions:
//
// Name           Meaning
// ----------------------------
// rd             Read
// wr             Write
// start          Start transaction
// advance        Advance beat (individual data transfer)
// f<signal>      Parsed data output of FIFO
// next_<signal>  DFF input
//
//-----------------------------------------------------------------------------
// Please refer to the databook for full details on the signals.
//
// These are found in the "Signal Description" section of the "Signals" chapter.
// There are details on the following
//   % Input Delays
//   % Output Delays
//   Any False Paths
//   Any Multicycle Paths
//   Any Asynchronous Signals
//
//leda NTL_CON10 off
//LMD: output tied to supply
//LJ : mready signal is tied to 1'b1 in LITE mode.
//leda NTL_CON10A off
//LMD: output tied to supply in top level module
//LJ : mready signal is tied to 1'b1 in LITE mode.
module M2_swerv_sram_DW_axi_gs(/*AUTOARG*/
//leda NTL_CON10A on
//leda NTL_CON10 on
  // Outputs

  awready, 
                 wready, 
                 bid, 
                 bresp, 
                 bvalid, 
                 arready, 
                 rid, 
                 rdata, 
                 rresp, 
                 rlast, 
                 rvalid,
                 maddr, 
                 mread, 
                 mwrite, 
                 msize, 
                 mburst, 
                 mlen, 
                 mlast, 
                 mdata, 
                 mwstrb, 
                 mready, 
                 // Inputs
                 aclk, 
                 aresetn, 
                 awid, 
                 awaddr, 
                 awlen, 
                 awsize, 
                 awburst, 
                 awlock, 
                 awcache, 
                 awprot, 
                 awvalid, 
                 wdata, 
                 wstrb, 
                 wlast, 
                 wvalid, 
                 bready, 
                 arid, 
                 araddr, 
                 arlen, 
                 arsize, 
                 arburst, 
                 arlock, 
                 arcache, 
                 arprot, 
                 arvalid,
                 rready, 
                 gclken, 
                 saccept, 
                 svalid, 
                 sdata,
                 sresp
                 );


// ----------------------------------------------------------------------------
// PORTS
// ----------------------------------------------------------------------------

  input                                       aclk;
  input                                       aresetn;
  input                                     gclken;

  //Write address channel
  input  [`GS_ID-1:0] awid;
  input  [`GS_AW-1:0] awaddr;
  input  [`GS_BW-1:0] awlen;
  input  [2:0] awsize;
  input  [1:0] awburst;
  input  [`AXI_LTW-1:0] awlock;
  //leda NTL_CON13C off
  //LMD: non driving port.
  //LJ : These signals are not actually required to be connected; They are not used 
  //     and therefore are not connected internal to the component.
  //leda NTL_CON37 off
  //LMD: Signal/Net must read from the input port in module.
  //LJ : These signals are not actually required to be connected; They are not used 
  //     and therefore are not connected internal to the component.
  input  [3:0] awcache;
  input  [2:0] awprot;
  input  wlast;  
  //leda NTL_CON37 on
  //leda NTL_CON13C on
  input  awvalid;
  output awready;
  //Write data channel
  input  [`GS_DW-1:0] wdata;
  input  [`GS_DW/8-1:0] wstrb;
  input  wvalid;
  output wready;
  //Write response channel
  output [`GS_ID-1:0] bid;
  output [1:0] bresp;
  output bvalid;
  input  bready;
  //Read address channel
  input  [`GS_ID-1:0] arid;
  input  [`GS_AW-1:0] araddr;
  input  [`GS_BW-1:0] arlen;
  input  [2:0] arsize;
  input  [1:0] arburst;
  input  [`AXI_LTW-1:0] arlock;
  //leda NTL_CON13C off
  //LMD: non driving port.
  //LJ : These signals are not actually required to be connected; They are not used 
  //     and therefore are not connected internal to the component.
  //leda NTL_CON37 off
  //LMD: Signal/Net must read from the input port in module.
  //LJ : These signals are not actually required to be connected; They are not used 
  //     and therefore are not connected internal to the component.
  input  [3:0] arcache;
  input  [2:0] arprot;
  //leda NTL_CON37 on
  //leda NTL_CON13C on
  input  arvalid;
  output arready;
  //Read data channel
  output [`GS_ID-1:0] rid;
  output [`GS_DW-1:0] rdata;
  output [1:0] rresp;
  output rlast;
  output rvalid;
  input  rready;
  //Low-power Channel
  
  //GENERIC SLAVE INTERFACE
  //Request Channel
  output [`GS_AW-1:0] maddr;
  output mread;
  output mwrite;
  output [2:0] msize;
  output [1:0] mburst;
  output [`GS_BW-1:0] mlen;
  output mlast;
  output [`GS_DW-1:0] mdata;
  output [`GS_DW/8-1:0] mwstrb;
  input  saccept;
  //Response Channel
  //leda NTL_CON13C off
  //LMD: non driving port.
  //LJ : These signals are not used in LITE mode. Internally generated versions of these signals are used.
  //leda NTL_CON37 off
  //LMD: Signal/Net must read from the input port in module.
  //LJ : These signals are not used in LITE mode. Internally generated versions of these signals are used.
  input  svalid;
  input  [1:0] sresp;
  //leda NTL_CON37 on
  //leda NTL_CON13C on
  input  [`GS_DW-1:0] sdata;
  output mready;


